INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (1, 'In the twenty first century it is thought to be difficult to define art.', 1, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2, 'It does not always exist in a gallery.', 2, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3, 'It is not always a solid object or a flat image.', 3, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4, 'It can be imagined, an action, a pledge, existing only temporarily, it can be made by one people or many, it can be an idea which accumulates over time.', 4, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5, 'It can exist in other realities and will exist in realities of which we do not yet know.', 5, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (6, 'It is thought not to be the servant of the state, of religion or of ritual, but to exist purely for its own sake.', 6, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (7, 'This subjective freedom is highly valued and often disputed.', 7, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (8, 'The one constant is that art is made by artists and that it is made for its own sake.', 8, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (9, 'It was not always this way.', 9, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (10, 'THE STORY OF ART', 10, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (11, 'The story of art is the story of the human urge to represent the world.', 11, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (12, 'This began before humans had acquired verbal language with the simple drawing of a line in the sand with a finger.', 12, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (13, 'In 6000 BC the indigenous groups of prehistoric humans in the continents of Europe, Africa and Asia, the Middle East, the Far East, Australasia and the Americas had not developed any forms of verbal or visual communication.', 13, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (14, 'There was no form of representation in the world.', 14, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (15, 'But as these peoples evolved and began to acquire language, conceptual and cognitive skills, they began to create tools.', 15, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (16, 'The first tool may have been a stick used to draw in the sand, or it may have been a stone used to crack a nut or to kill an animal.', 16, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (17, 'PREHISTORIC ART', 17, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (18, 'Tools and visual representations are the first evidence we have of the existence of early civilisations.', 18, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (19, 'The earliest examples of these have been found in Africa, the home of the Neanderthals from whom all humans are descended.', 19, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (20, 'Prehistoric people were developing forms of representation before the discovery of fire.', 20, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (21, 'We know this because some of their drawings and tools have survived.', 21, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (22, 'Art, or the evidence of people&#x2019;s urge to record their life, is the oldest surviving evidence of human endeavour.', 22, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (23, 'It may be the case that music, probably in the form of rhythm, is an older form of human expression but only drawing, artefacts and objects have permanence.', 23, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (24, 'This is why they are assigned such great value in western culture where linear history is the primary means of self definition.', 24, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (25, 'Many other cultures do not place the same emphasis on history.', 25, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (26, 'Their artefacts and art are different.', 26, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (27, 'In the beginning art may have been pure representation.', 27, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (28, 'We do not know whether there was a purpose to art other than pure self expression because there are many examples of prehistoric art whose purpose is unknown to us.', 28, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (29, 'There are lines drawn in the desert in South America that form geometric patterns visible only from the air, patterns scratched and carved into rock, and the countless temporary forms of expression that have been washed or blown away.', 29, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (30, 'THE STONE AGE', 30, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (31, 'As humans evolved, their visual representations became part of the rituals they created around the most important aspects of life, fertility, birth, death and the hunting for food.', 31, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (32, 'Art began to have a specific function.', 32, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (33, 'The earliest surviving images are scratched into stone, and consist mostly of lines, for example the cave paintings at Lascaux in France.', 33, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (34, 'These and others like them depict people hunting animals, in the case of Lascaux a buffalo like creature.', 34, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (35, 'The paintings are drawn in outline on the wall using paints made of earth and soot based pigments, in ochre, reddish brown and black.', 35, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (36, 'There are groups of lines too which are unexplained but seem to function as a way of counting or as a visual dynamic.', 36, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (37, 'As prehistoric people developed more sophisticated tools, they discovered a greater variety of ways of making marks.', 37, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (38, 'Flints could be chipped to make sharp blades with which to cut animal skin, animal hair, and to pulverise plants, earth and clay.', 38, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (39, 'The discovery of fire meant that substances for drawing, painting and modelling could be dried, heated, reduced, distilled and fire provided soot, ash, charcoal and light.', 39, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (40, 'THE IRON AGE', 40, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (41, 'Iron age people had a much greater range of tools and implements.', 41, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (42, 'They had begun to fashion utensils and to make personal adornments from metal, as well as tools and weapons and with these came the development of decoration.', 42, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (43, 'Objects began to have greater value and the degree and type of their decoration began to be significant.', 43, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (44, 'At the same time Iron Age people also began to acquire language.', 44, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (45, 'One of the first groups to produce metal vessels for eating and drinking was the Beaker people.', 45, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (46, 'Often these objects were decorated with images of animals, vitally important as a source of food.', 46, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (47, 'ABORIGINAL ART', 47, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (48, 'In Australasia, the aboriginal people developed an entirely different form of representation.', 48, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (49, 'Early aboriginal art was a language of symbolic representation in which pattern and symbol is used to represent the world.', 49, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (50, 'Drawings were made using different colours of sand and earth straight onto the ground.', 50, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (51, 'These described the land and its spirits, and depicted time as a journey.', 51, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (52, 'The drawings were temporary and not always shown to everybody, sometimes even being made in isolation.', 52, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (53, 'Different cultures developed different views of the world according to their geographical location, the climate and the food that was available to them.', 53, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (54, 'During the Iron Age people from other continents developed along different paths leading to a material expression of cultural difference.', 54, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (55, 'THE BRONZE AGE', 55, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (56, 'The smelting of metals led to the discovery of a range of alloys, the first being bronze.', 56, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (57, 'These metals could be fashioned more intricately and finely allowing for greater precision and decorative effect such as repeating patterns, beaten metal and thin wire.', 57, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (58, 'EARLY CIVILISATIONS', 58, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (59, 'The earliest civilisations were formed as people began to travel further in search of food and hospitable land and to encounter other groups both aggressively and peaceably.', 59, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (60, 'Humans had previously been nomadic but some groups began to make permanent settlements and with these came buildings and monuments.', 60, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (61, 'Cave painting and rock carving had been the only permanent sites for art until the construction of permanent dwellings.', 61, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (62, 'Settlement gave rise to the construction of stone buildings, burial chambers and monuments all of which could be decorated or contain representation.', 62, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (63, 'For nomadic people portability had been a factor but now larger and heavier objects were produced and people began to make figurative sculptural representations from stone, clay and wood.', 63, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (64, 'Stonehenge, the great stone circle in Britain which was built in the Stone Age to celebrate the solstice, is a construction which is not decorated but is not a dwelling.', 64, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (65, 'It is an early church.', 65, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (66, 'Subsequently buildings that were the focus for ritual whether pagan or religious became the most highly decorated anywhere.', 66, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (67, 'Art and architecture began to be closely linked.', 67, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (68, 'After the Bronze Age the great early civilisations of the world developed in isolation, reaching their peaks in terms of population, claims to territory and cultural attainment at different periods in history.', 68, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (69, 'Pre Columbian art', 69, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (70, 'The pre Columbian people in south America made some of the most sophisticated early sculpture.', 70, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (71, 'Their stone male and female figures have distinctive flattened and squared forms, with large featured faces.', 71, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (72, 'Later in South America the Mayan Aztec and Inca civilisations became very skilful in the use of gold.', 72, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (73, 'In Africa, the Sumerians and Abyssinians and many other cultures developed widely different forms of visual expression, both in the adornment of the body and dwellings, and in the production of artefacts.', 73, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (74, 'TRIBAL ART', 74, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (75, 'In all the continents of the world large numbers of people continued to live as tribes, some settled and some nomadic, rarely coming into contact with other peoples and each with its own cultural specificity.', 75, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (76, 'Native Americans, semi nomadic peoples who lived off the plains of America, used leather, beads, feathers and wood, and are today customarily symbolised by the Totem Pole, a ritual sculpture.', 76, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (77, 'Melanesian and Polynesian peoples that depended on the sea for their livelihood used wood, shells and pounded tree bark to make the tapa cloth which they printed with symbolic designs.', 77, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (78, 'Their boats were adorned with the work of their most skilled artists.', 78, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (79, 'The Inuit who inhabited the frozen north of America carved from soft stone.', 79, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (80, 'The African subcontinent yielded the largest number of distinct tribes, for example the Nuba, Yoruba, Dogon, Masai and Zulu.', 80, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (81, 'Africa was one of the culturally richest parts of the world.', 81, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (82, 'EMPIRES', 82, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (83, 'The earliest civilisations soon built cities and with cities came armies and battles for territory.', 83, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (84, 'Soon empires were formed, the earliest being the Byzantine, Ottoman, the Roman empire, the Japanese and Chinese empires which were ruled by successive dynasties.', 84, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (85, 'Greece is often referred to as the cradle of civilisation and early Greek culture was the most sophisticated in the world.', 85, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (86, 'The development of religions was very significant in terms of the history of art was religion became the focus of a large proportion of artistic activity.', 86, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (87, 'ART AND RELIGION', 87, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (88, 'Religions divided the world and generated an unprecedented quantity of visual art.', 88, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (89, 'Many parts of the world remained pagan, worshipping local gods with their own iconography and ritual.', 89, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (90, 'The Greeks, for example, had a complex family of pagan gods and myths.', 90, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (91, 'Larger religions began to spread: in the east, Islam, the religion of the Ottoman empire predominated, and in the middle east Christianity.', 91, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (92, 'In Asia Hinduism and Islam co existed although not necessarily in harmony and in China and Japan Buddhism and Taoism were predominant.', 92, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (93, 'Many Northern Europeans such as the Celts, Norse and the Vikings, were pagans.', 93, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (94, 'A burial ship found at Sutton Hoo in Britain contained many examples of Viking art.', 94, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (95, 'The ancient Egyptians had their own gods.', 95, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (96, 'Art had been an important part of ritual.', 96, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (97, 'It now became a servant of the state and of religion and in the process the works that have become known as some of the greatest works of art were created.', 97, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (98, 'Artists became the producers of religious iconography but of course in Islamic areas no figurative representation appeared anywhere since Islam does not permit it.', 98, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (99, 'EARLY WRITTEN TEXT', 99, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (100, 'Writing is a very important influence on art during the period leading up to the birth of Christ and afterward.', 100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (101, 'It is thought that writing was developed by the Sumerians and that Sanskrit may be the oldest written language.', 101, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (102, 'The earliest surviving artefacts are the Dead Sea scrolls, written in Sanskrit on papyrus, and the Rosetta stone, an inscribed tablet.', 102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (103, 'Writing was a new way of describing and recording the world which had previously been exclusively visual and for centuries writing was a skill learned only by the very few.', 103, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (104, 'Visual imagery remained the primary means of communicating and recording events, but as writing began to tip the balance, art was led to fulfil new functions.', 104, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (105, 'EGYPTIAN ART', 105, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (106, 'The ancient Egyptians developed an early writing system called hieroglyphics.', 106, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (107, 'They were a wealthy trading civilisation with a highly sophisticated system of government and constructed some of the greatest buildings and monuments ever made, the Pyramids, the Sphinx and the statues of the pharaohs in the Valley of the Kings.', 107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (108, 'The Egyptians worshipped deities such as Isis and Osiris and held cats, certain birds and scarab beetles to be sacred.', 108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (109, 'Egyptian art is seen at is most spectacular in the tombs of the pharaohs.', 109, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (110, 'They believed in the afterlife, therefore the art that has been found in Egyptian tombs is a good indicator of the life of the living.', 110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (111, 'Egyptian artists were skilled in carving, casting and gold and silver smithing.', 111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (112, 'They had a style of drawing that is very distinctive &#x2013; all figures are shown with their body facing forward and the head in profile.', 112, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (113, 'Hieroglyphs use this style too in the creation of long vertically written texts consisting of pictograms.', 113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (114, 'Egyptian two dimensional art emphasises flatness and uses no perspective but in contrast Egyptian sculpture is very realistic.', 114, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (115, 'A cat has been found carved from black stone and wearing a jewelled collar, for example, and countless sarcophagi for mummified pharaohs bare lifelike effigies.', 115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (116, 'The sphinxes and the pharaohs carved on a monumental scale, forty metres high, are in proportion and physiologically accurate.', 116, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (117, 'ETRUSCAN ART', 117, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (118, 'Etruscan pottery is known for the quality of its form and decoration.', 118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (119, 'BYZANTINE ART', 119, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (120, 'The Byzantine empire was one of the largest empires in the world.', 120, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (121, 'Byzantine art is valued for the quality of figurative drawing and painting that had developed physiological accuracy, realism and early use of perspective.', 121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (122, 'GRECO ROMAN ART', 122, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (123, 'Around 400 BC the Greeks had developed a civilisation that was pre eminent.', 123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (124, 'The Greek system of government was the model for all modern nations.', 124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (125, 'The Greeks had a written language, and a flourishing culture.', 125, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (126, 'Greek sculpture was the most realistic in the world, and it was at this time that the idea that art should aspire to realism began to take root.', 126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (127, 'Greek sculptures were generally of white marble or other stone, and often painted in bright colours.', 127, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (128, 'The best known Greek sculptures are the Elgin marbles, subject of a protracted battle between Britain, who has possession of them and Greece, who wants them back.', 128, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (129, 'The marbles once adorned the frieze of one of the most famous buildings of antiquity, the Parthenon in Athens.', 129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (130, 'The Venus de Milo, a classical Greek sculpture, is perhaps the best known sculpture of the western world, considered to represent perfection of female form and becoming a byword for artistic skill and beauty.', 130, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (131, 'It is made in white marble and at some point since antiquity has suffered the loss of its arms.', 131, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (132, 'Greek vases are very finely decorated by incising into the black glaze which covers the red clay from which they are made.', 132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (133, 'They are renowned for the quality and realism of the drawing.', 133, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (134, 'Greek art was for centuries to be seen as the benchmark for all art, and Classical Greece provided the model for the Roman Empire, whose cultural achievements dominated Europe for centuries after the Empire fell.', 134, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (135, 'The Romans built cities, roads and infrastructure on a vast scale and created art to decorate their empire and venerate their leaders.', 135, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (136, 'The carved stone Roman portrait bust is a good example, of which there are countless examples surviving.', 136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (137, 'Many archaeological sites have revealed the variety of Roman art, for example Herculaneum, Pompeii, two towns that were destroyed but preserved for centuries by the eruption of the volcano Vesuvius.', 137, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (138, 'Mosaic wall decorations and paintings revealed after excavation in the nineteenth century show mosaic floor designs featuring food and fish, and murals depicting sports such as leaping over a bull&#x2019;s horns and dolphins.', 138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (139, 'Knossos in Crete also has excellent murals, whilst Volubilis and Lullingstone Villa in Britain contain similar but smaller scale work.', 139, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (140, 'Roman art spread so widely that it became a dominant style, Romanesque, as artists, artisans and craftspeople adapted and personalized it.', 140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (141, 'Many cathedrals and churches in Europe were built in this style for the next 200 hundred years as Catholicism developed.', 141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (142, 'ISLAMIC ART', 142, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (143, 'At the same time in the middle east and in Asia, Islam spread, bringing its own cultural identity to the towns and cities of the Ottoman empire.', 143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (144, 'Islam demanded that there be no figurative representation of any kind, whether in architectural decoration, textiles, book, fabric, painting or sculpture.', 144, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (145, 'This was because the word by which the teachings of Mohammed had been handed down, was itself sacred, and so the word became the only permissible imagery.', 145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (146, 'Written text was rendered as decorative design, carving and patter, and calligraphic patterns of remarkable complexity were carved into stone to adorn mosques for example.', 146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (147, 'Carpets for which the area then known as Persia became so famous, depicted animals, plants and buildings symbolically.', 147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (148, 'For centuries there was no art produced in Islamic parts of the world that represented a human face.', 148, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (149, 'CHINESE ART', 149, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (150, 'By contrast in the far east, home of Buddhism, representational painting and sculpture featured amongst the highest achievements of artists.', 150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (151, 'Japan and China have produced the finest clay sculpture in the world, for example the glazed clay horses of the Tang dynasty and the terracotta army found buried in the late twentieth century.', 151, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (152, 'This consists of hundreds of statues of warriors buried in a shallow underground tomb.', 152, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (153, 'Chinese writing is not pictographic but the characters have a visual element.', 153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (154, 'Chinese art therefore has a strong tradition in calligraphic art.', 154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (155, 'Chinese watercolours have calligraphic brushstrokes made quickly which represent plants, landscape, particularly mountains, and sometimes animals and birds.', 155, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (156, 'Chinese paintings were made on silk that was readily available rather than canvas.', 156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (157, 'Painting on silk required soft small brushes and thin paint.', 157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (158, 'Since Buddhism did not depend on graphic illustration, religious iconography never became an intrinsic part of daily life.', 158, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (159, 'However Buddha was widely represented in statue form, from the smallest pocket carving to the largest stone or metal figures such as the reclining gold Buddha that is still famous today.', 159, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (160, 'JAPANESE ART', 160, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (161, 'Clay and porcelain modelling is an important element of Japanese art, seen in the ceramics of the Sung and Ming eras which reached a pinnacle of excellence which was not surpassed anywhere else.', 161, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (162, 'Japanese ceramics are famous all over the world and their influence continues to be seen in contemporary ceramics and mass produced porcelain both in the form and in the decoration.', 162, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (163, 'Japanese ceramics were an intrinsic part of the tea ceremony, an important daily ritual in Japanese life.', 163, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (164, 'Japanese watercolours and woodblocks are well known too.', 164, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (165, 'The Japanese were skilled in the making of paper and the production of silk.', 165, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (166, 'Although Buddhism has its place in Japan, Confucianism was widely followed, and this was more a philosophical teaching than a religion.', 166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (167, 'No religious iconography was attached to Confucianism.', 167, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (168, 'The opposing but complementary and essential principles of yin and yang influence much Japanese art.', 168, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (169, 'They can be seen in the many representations of landscape and weather, in particular rocky mountains with stylised swirling wind and cloud, and in similar sculptures which are large chunks of rock with especially appreciated forms.', 169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (170, 'Japanese art has a flatness to it, a lack of deep perspective, that has prevailed for centuries.', 170, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (171, 'The famous willow pattern, a Victorian interpretation of traditional Japanese art, shows a never ending landscape that exists all on one plane.', 171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (172, 'CHRISTIAN ART', 172, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (173, 'After the spread of Christianity a new kind of art began to emerge.', 173, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (174, 'Christianity was an iconographic religion based on the worship of a god with a human form, his son Jesus, a human, and Mary his mother.', 174, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (175, 'The depiction of these three has given rise to some of the greatest and most influential art in the western world.', 175, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (176, 'For a period of several hundred years, from the Medieval period to the seventeenth century and the Enlightenment, most significant art had a religious theme or was commissioned by the Church.', 176, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (177, 'The rulers of Europe were considered to rule by divine right, putting art also into the service of the state.', 177, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (178, 'Early Christian art, such as the Coptic tapestries, the earliest surviving woven textiles that depict Christ and Mary, are simple and show images of the face of Christ.', 178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (179, 'Wherever Christianity spread, local artistic styles were put to the service of the church, resulting in multiple representations of the same three people with local regional and ethnic features.', 179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (180, 'But there are constant elements &#x2013; God is usually shown as an old man with a white beard, Christ as a young man with long brown hair and a beard and Mary as a young woman with long black or brown hair.', 180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (181, 'Judaism, like Islam, did not permit representation in any form, its teachings being transmitted through words and closely prescribed laws governing everyday life.', 181, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (182, 'So for a time early representational art was essentially a Christian endeavour.', 182, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (183, 'In the early medieval period many churches had fresco paintings in them and these frescos are some of the earliest surviving paintings that we have today.', 183, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (184, 'During the period in which Islam, Christianity and Judaism were expanding, very few people were literate apart from the clergy and members of the ruling classes.', 184, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (185, 'Visual imagery was still the primary means of mass communication.', 185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (186, 'The Bayeux tapestry, as late as the eleventh century was made as a piece of news reportage after the fact to tell the story of the battle of Hastings through images.', 186, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (187, 'These images acted as a prompt for the spoken word &#x2013; a storyteller would stand in the hall in which the tapestry hung around all four walls and tell the tale.', 187, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (188, 'The diagonal marks in the borders of the tapestry are thought to add some kind of rhythmic dynamic to the spoken word.', 188, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (189, 'With the invention of printing and the dissemination of the Bible, literacy improved.', 189, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (190, 'The dissemination of visual images through print was more democratic.', 190, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (191, 'MEDIEVAL ART', 191, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (192, 'In the Middle Ages, the influence of the Romans was still pervasive.', 192, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (193, 'Romanesque and Gothic art and architecture dominated northern Europe, but towards the south the influence of the moors was seen in Spanish and Portuguese art.', 193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (194, 'In the east Islamic art and architecture mixed with pockets of Christianity and Judaism led to a non representational art, but in the far east in China, Japan, and in Russia, visual art was representational.', 194, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (195, 'Lucas Cranach', 195, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (196, 'The work of Lucas Cranach, a German medieval artist working in the 1300s is a good example of northern European religious art.', 196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (197, 'Cranach painted an altarpiece that was shocking at the time since it accurately depicted the misery suffered by Christ on the cross, the pain and the physical degradation.', 197, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (198, 'Cranach also showed the plight of ordinary people of the time by painting them with festering sores, deformities and other afflictions.', 198, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (199, 'He painted very realistically in quite bright colours.', 199, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (200, 'Matthias Grunewald', 200, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (201, 'Grunewald, a German medieval artist working around 1350, is also known for his crucifixion scenes and for the gritty realism of his paintings, extraordinary for the time, and for their use of colour.', 201, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (202, 'Hieronymous Bosch', 202, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (203, 'Another German painter, Bosch, painted a version of heaven called The Garden of Earthly Delights.', 203, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (204, 'This extremely well known painting is a small triptych approximately 70 cm tall with a square central panel and two rectangular side panels.', 204, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (205, 'Bosch&apos;s painting depicts paradise as an extraordinary place, with dreamlike creatures and objects, some beautiful pink glass spheres, some castles and towers.', 205, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (206, 'It is an early precursors to fantasy and science fiction illustration, being full of fantastical creations of Bosch&#x2019;s imagination.', 206, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (207, 'The painting is very detailed in its composition and execution.', 207, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (208, 'Peter Breughel the Elder', 208, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (209, 'Breughel&#x2019;s work depicts medieval everyday life.', 209, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (210, 'A Dutch painter working in the 1400s, Breughel is known for his instantly recognisable paintings of the seasons, for example Hunters in the Snow.', 210, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (211, 'In each case the painting shows a village scene, with a large number of peasants, children and domestic animals going about their everyday life inside and outside buildings and dwellings.', 211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (212, 'There is activity in every corner of the painting, down to the smallest detail such as a person urinating, or a dog stealing some meat, a couple kissing, children being naughty, someone sleeping.', 212, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (213, 'The scenes are realistically painted and are notable for their depiction of the lives of ordinary people with no imposed narrative, no moral or religious overtones, no theme other than the representation of life as it was.', 213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (214, 'The colours, the drawing of landscape, vernacular, architecture, the detail of the clothing, of tools and household items makes these works extraordinary documents of their time.', 214, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (215, 'Above all Breughel&#x2019;s paintings of the seasons present four very different atmospheres and moods.', 215, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (216, 'The paintings are so famous as to be instantly recognisable whether or not the Breughels&#x2019;s name is known, and are used on calendars, merchandise and in advertising the world over.', 216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (217, 'Peter Breughel the Younger', 217, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (218, 'A Dutch painter related to Breughel the Elder.', 218, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (219, 'In the south of Europe, especially in Italy, painters were developing new ways of working.', 219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (220, 'Many such as Piero di Cosimo, Antonello da Messina, Fra Angelico and Piero della Francesca were making frescos or wall paintings in monasteries and churches.', 220, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (221, 'Antonello Da Messina', 221, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (222, 'Da Messina was an Italian renaissance painter who made a painting of Saint Jerome in his study.', 222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (223, 'This shows the room as a box like structure that sits on its own in a landscape, giving the viewer access through the open front wall.', 223, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (224, 'What we are seeing is monk&#x2019;s cell consisting of two linked rooms made of dark coloured wood in one of which the saint is seated at a desk.', 224, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (225, 'Piero Della Francesca', 225, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (226, 'This Siennese painter is perhaps the best known of the Italian late medieval period.', 226, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (227, 'In the 1450s Della Francesca painted a number of notable frescos in churches in central Italy, in particular an image of the Virgin Mary, pregnant and standing in a landscape with a tree, that can be seen significantly restored in a tiny village near Siena.', 227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (228, 'His painting of the baptism of Christ shows Christ being baptised by John the Baptist who is standing in a stream wearing a cloth round his loins.', 228, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (229, 'The Italian countryside, representing the Middle East, stretches away in the background.', 229, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (230, 'Artists from this period understood how to use foreground and background to create a sense of three dimensional space.', 230, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (231, 'THE RENAISSANCE', 231, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (232, 'The fifteenth century saw a flowering of western culture centred around Italy.', 232, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (233, 'The dominance of the Catholic church and the wealth of the ruling families like the Medicis, led to a great number of artists being commissioned to make religious paintings for countless churches as well as many portraits.', 233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (234, 'The artists of this period are acknowledged to be among the greatest in the Western world.', 234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (235, 'Italian artists such as the painters Lorenzo de Ghiberti, Fillipo Lippi, Lorenzo Lotto, Lorenzo Ghiberti and Simone Martini made many paintings depicting scenes from the life of Christ set in the Italian countryside and with Italian architecture and clothes.', 235, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (236, 'Lorenzetti', 236, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (237, 'Lorenzetti&#x2019;s Good and Bad Government can be seen in Siena.', 237, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (238, 'This painting is the width of a room, situated high up near the ceiling and it shows a fortified city on a hill in the distance with its people going about their daily lives.', 238, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (239, 'A man on a horse is riding into the image from left in the foreground, the horse has a white coat on and the man is wearing armour.', 239, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (240, 'Good and Bad Government is unusual for its depiction of an entire community and its attempt to represent democracy in action in a painting.', 240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (241, 'Giorgione', 241, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (242, 'Giorgione was an Italian artist who painted The Flagellation of St Jerome, depicting the middle aged saint with a thin sagging body, long grey hair and a beard, alone in penitent pose in his room, naked save for a red cloth around his loins.', 242, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (243, 'Jerome is surrounded by symbolic objects and is in the act of scourging himself with a long leather whip.', 243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (244, 'During the Renaissance artists began to study techniques and materials with a scientific approach.', 244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (245, 'New pigments, painting techniques and materials were discovered and casting techniques for sculpture were refined.', 245, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (246, 'THE AGE OF PATRONAGE', 246, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (247, 'The renaissance was the great age of patronage.', 247, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (248, 'Artists who were commissioned by the Church or the State were in a position to afford assistants and to establish studios.', 248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (249, 'They took on apprentices who were employed to draw out paintings, mix colours, prepare canvases, under paint, and often to paint backgrounds &#x2013; including trees, grass, or patterns on fabric.', 249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (250, 'Many old master paintings are in fact the work of a number of people which has sometimes made attribution difficult.', 250, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (251, 'An artist&#x2019;s assistant might also go on to set up their own studio, and to paint in a very similar style to that of their master, so that it has often been difficult to tell who painted what.', 251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (252, 'If the painter of a particular work could not be established it was often attributed as being painted in a style similar to, or &#x2018;after,&#x2019; a certain master painter.', 252, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (253, 'Andrea Mantegna', 253, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (254, 'Mantegna, an Italian renaissance painter, is known for his many great paintings and for his invention of the painting technique grisaille.', 254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (255, 'PERSPECTIVE', 255, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (256, 'The discovery during the renaissance which had the most significant effect on painting was that of perspective.', 256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (257, 'This was a landmark in the history of visual representation since it enabled artists to depict three dimensional space for the first time.', 257, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (258, 'There were many theories of perspective but the most significant element was the establishment of the vanishing point.', 258, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (259, 'This was an imaginary point in the vertical centre of the canvas, about one third down from the top, at which all sightlines from the position of the viewer converged, giving an illusion of three dimensional space.', 259, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (260, 'In particular, perspective enabled a far greater accuracy in the depiction of the built environment.', 260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (261, 'Complex theories tried to show that there could be a perspective that enabled the illusion to be effective from every viewing angle.', 261, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (262, 'Perspective was essentially an illusion constructed through geometry but in the Renaissance it was thought to be a two dimensional replication of what the human eye actually saw.', 262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (263, 'Leonardo Da Vinci', 263, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (264, 'One renaissance artist blended science and art more successfully than any other.', 264, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (265, 'Leonardo da Vinci is often seen as the quintessential Renaissance Man who defined the era.', 265, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (266, 'He worked as a court artist for the Medici family in Venice and did not paint only religious subjects.', 266, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (267, 'Da Vinci is arguably the most famous artist in the world, or has certainly made the most famous painting, the Mona Lisa, which has been reproduced by the billion, forged and stolen many times and still draws huge crowds to its site on the walls of the Louvre museum in Paris.', 267, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (268, 'This painting depicts a woman shown head and shoulders turned very slightly to one side.', 268, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (269, 'She has on a simple yellowish gold dress, a plain necklace and has brown hair.', 269, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (270, 'She does not look particularly wealthy.', 270, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (271, 'There is a landscape in the background.', 271, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (272, 'There is an inscription LHOQ below her on a painted scroll.', 272, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (273, 'What made the painting so famous is the woman&#x2019;s expression, in particular her smile.', 273, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (274, 'She seems to be looking straight at the viewer, and has a look of cool calm appraisal, the hint of a smile on her lips.', 274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (275, 'However her eyes seem to be fixed on the viewer wherever they stand in relation the painting, leading to the myth that the Mona Lisa is actually following the movements of her viewers, that she is somehow real.', 275, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (276, 'This is an extraordinary achievement for a painting that has come to symbolise great beauty.', 276, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (277, 'The term Mona Lisa has almost become an adjective to describe a beautiful woman.', 277, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (278, 'The myth attached to the painting has led to many copies being made and to the work featuring in other artists work, in advertising, in newspaper cartoons and is in fact an image that has currency everywhere in the Western World and often beyond.', 278, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (279, 'Mona Lisa copies appear in fairgrounds with holes cut for heads so that people can be photographed as her.', 279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (280, 'Automatic photo booths have the Mona Lisa as a backdrop or as a body for the sitter&#x2019;s head shot.', 280, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (281, 'Copies of her with the eyes cut out have been used in films for comedic effect &#x2013; someone behind the painting will look through the eye hole so that it appears that she is following a person around the room and Marcel Duchamp famously graffitied a moustache onto a reproduction of her.', 281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (282, 'The author of this image succeeded in painting a very beautiful portrait, but it is only one of his achievements.', 282, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (283, 'He made many religious paintings and altarpieces.', 283, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (284, 'A cartoon for a Madonna and child is particularly well known.', 284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (285, 'He did a vast number of drawings from the models, paying endless attention to hands and feet, eyes or other parts of the body, drawing them separately to get them right.', 285, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (286, 'Da Vinci was a polymath and his interests extended to anatomy and engineering.', 286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (287, 'He performed many dissections and recorded what he saw in drawings, expanding his sense of how to draw the human form this way as well as his medical knowledge of how the human body worked, even drawing a foetus still inside a woman&#x2019;s uterus.', 287, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (288, 'Another famous work by Da Vinci is a pen and ink drawing called The Golden Section.', 288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (289, 'A male figure with flowing hair is drawn standing with both arms stretched out horizontally and one leg pointed outwards at an angle.', 289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (290, 'Measured lines radiate from the figure, which represents the proportions taken from the human body used to make perspective and on which architectural construction is based.', 290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (291, 'A copy of this drawing was placed on the Moon by the crew of the Apollo in the 1960s.', 291, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (292, 'Da Vinci was also an inventor; he was so interested in the myth of Icarus that he built a flying machine.', 292, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (293, 'Sandro Botticelli', 293, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (294, 'Another well known Italian painter working around 1540 is best known for his painting The Nativity and The Birth of Venus, and also for his illustrations to Dante&#x2019;s Inferno.', 294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (295, 'Botticelli&#x2019;s The Birth of Venus is one of the most recognised images in the western world due to its frequent use in advertising.', 295, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (296, 'The very beautiful Venus is standing in a giant clam shell which floats on the sea, just away from the shore.', 296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (297, 'She is naked but her long hair covers her pubic area.', 297, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (298, 'She is surrounded by cherubs who pull the clam shell along by blue ribbons.', 298, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (299, 'Pale pink roses fall around her from the sky.', 299, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (300, 'The whole painting is rendered in luminous pale shades of blue, pink and sand colours.', 300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (301, 'The Nativity is a small painting about fifty cm tall and is certainly one of the best known nativity scenes ever painted.', 301, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (302, 'The stable is set in a forested landscape, with a timber and straw shelter in the centre of the picture which houses the Holy family.', 302, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (303, 'The shelter has no walls.', 303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (304, 'The Mary is seated with Jesus on her lap.', 304, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (305, 'Joseph kneels beside her.', 305, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (306, 'The shepherds are there.', 306, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (307, 'The ox and ass are in the shadows at the back of the stable.', 307, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (308, 'Above the thatched roof are angels, arranged in a row, some blowing trumpets or playing harps, their feet dangling, their softly coloured red blue and purple robes falling in folds around them, with gilded belts and halos hovering.', 308, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (309, 'Above the angels heaven can be seen though breaks in the clouds, and there are cherubs everywhere.', 309, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (310, 'Below the stable is a twisting path that leads to the bottom of the painting crossing horizontally, turning again and again, until the flames at the mouth of hell are reached.', 310, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (311, 'All along the path are devils poking out of burrows enticing lost souls; they have black skin, horns and forked tails.', 311, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (312, 'A similar but smaller work, The Birth of Ezra, predates this painting.', 312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (313, 'Botticelli made a series of drawings to illustrate Dante&#x2019;s Inferno.', 313, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (314, 'These show the different levels of purgatory and the sins associated with each level and graphically illustrate the particular torture or punishment inflicted on the lost souls.', 314, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (315, 'The route to heaven is then shown culminating in the entry in o heaven, which is a beautiful garden.', 315, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (316, 'The drawings are made for a book, done in dark brown ink and are very detailed.', 316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (317, 'Van Eyck', 317, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (318, 'Around the same time, Van Eyck made a painting called the Arnolfini Marriage which is particularly well known.', 318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (319, 'The painting shows a wedding couple standing side by side.', 319, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (320, 'The woman is wearing a long dark green dress and holds one hand up, palm toward the viewer.', 320, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (321, 'There is a landscape in the background.', 321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (322, 'Sculpture also developed rapidly in the renaissance.', 322, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (323, 'Artists began to measure their models with callipers and develop tools, metal alloys and casting and carving methods that enabled them to create realistic simulations of the human form.', 323, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (324, 'Sculpture studios had enough employees to enable the handling of large blocks of stone and the construction of foundries.', 324, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (325, 'Donatello', 325, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (326, 'Donatello is one of the greatest renaissance sculptors.', 326, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (327, 'Benvenuto Cellini', 327, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (328, 'An Italian renaissance sculptor and goldsmith, Cellini was working around 1540.', 328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (329, 'His made a bronze statue of David with which he attempted to rival Michelangelo and also made a bronze of Medusa.', 329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (330, 'Cellini was well respected for his skill as a goldsmith and his work was much in demand with the Medici family.', 330, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (331, 'An extravagant gold salt cellar in the form of an ornate clam shell containing Neptune and many sea nymphs is particularly well known.', 331, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (332, 'The salt cellar was stolen in 2003.', 332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (333, 'Cellini wrote an outspoken and lengthy autobiography which details the rivalry between artists&#x2019; studios.', 333, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (334, 'Michelangelo', 334, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (335, 'The greatest renaissance sculpture is generally acknowledged to be a figure of the biblical David which was made by the sculptor and painter Michelangelo to represent ideal male beauty.', 335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (336, 'This white marble figure of a nude man is larger than life, about six metres high, and was radical at the time for its naturalism and the physiological accuracy with which it was modelled.', 336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (337, 'Michelangelo applied the lessons of perspective to the sculpture, making the feet proportionally larger than they should have been.', 337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (338, 'Several smaller versions were made from bronze.', 338, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (339, 'This sculpture was much copied and inspired much debate in the studios of Florence.', 339, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (340, 'Michelangelo was an Italian artist working in Florence who is universally known as one of the greatest artists of all time, his name often being used to invoke the idea of the highest achievement in art.', 340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (341, 'Michelangelo is as well known for his fresco on the ceiling of the Sistine Chapel showing the life of Christ and the ascension into heaven.', 341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (342, 'He was a very skilled draughtsman and created very lifelike figures using colour in a realistic way and painting flowing drapery.', 342, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (343, 'The Sistine chapel ceiling was an enormous undertaking and to paint it Michelangelo and his assistants spent a year lying on their backs on scaffolding towers.', 343, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (344, 'Images from the ceiling are known all over the world, often used by advertisers, and have become almost generic.', 344, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (345, 'One part of the fresco is most frequently reproduced, the image of Christ&#x2019;s outstretched hand reaching out to the hand of God, their fingers nearly touching.', 345, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (346, 'This is an image of great tension and portent, and it seems as if an electrical charge passes from one to the other through their fingers.', 346, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (347, 'In the late 1990s the ceiling was cleaned, provoking a great deal of controversy since for centuries the fresco had been darkened and the colours muted.', 347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (348, 'The fresco had been known to visitors and to those looking at reproductions as an antique, parts of which were even obscured from view by centuries of dirt and the breath of millions of visitors.', 348, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (349, 'By contrast the cleaned ceiling seems very brightly coloured, even garish.', 349, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (350, 'Michelangelo also made a marble sculpture of the Pieta.', 350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (351, 'By the end of the fifteenth century the fame of Italian masters had spread throughout Europe.', 351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (352, 'Artists began to look beyond religious and political subjects to the myths of classical Greece which were sometimes used as metaphors for contemporary events.', 352, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (353, 'Classicism was the dominant theme for artists in the sixteenth century such as Poussin, El Greco, Raphael and Titian.', 353, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (354, 'Very few artists were women.', 354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (355, 'Artemesia Gentileschi is a rare exception although there may have been more of whom there is no record.', 355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (356, 'Artemesia Gentileschi', 356, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (357, 'An Italian artist who is the best known woman painter of the classical period, Gentileschi&#x2019;s most frequently cited work is a portrait of a woman and a painting of the Martyrdom of St Catherine.', 357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (358, 'El Greco', 358, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (359, 'Most of the well known artists of the fifteenth and sixteenth centuries are Italian or Spanish.', 359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (360, 'El Greco, &#x2018;the Greek&#x2019;, is an exception.', 360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (361, 'He made paintings using loose brushstrokes with bold colours.', 361, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (362, 'Caravaggio', 362, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (363, 'Caravaggio is another classical Italian painter.', 363, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (364, 'He painted in a more precise and well worked way than Titian, for example, and was known for his complex compositions.', 364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (365, 'Caravaggio invented chiaroscuro, a way of painting using only the lightness and darkness in a scene.', 365, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (366, 'One painting by him shows a scene of bacchanalian revelry, a number of semi clad young men wearing ivy wreaths in their hair.', 366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (367, 'Nicholas Poussin', 367, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (368, 'A French classical artist who made precisely drawn and richly coloured paintings which have a theatrical atmosphere.', 368, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (369, 'The figures in Poussin&#x2019;s paintings are painted in very bright colours and posed to look as if they are immobile and the scenes he depicts often look staged rather than natural.', 369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (370, 'For this reason he fell out of favour for some time and not much was known about him.', 370, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (371, 'Poussin was rediscovered in the early twentieth century by the art historian Anthony Blunt who wrote a catalogue raisonn&#xe9;.', 371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (372, 'Bernini', 372, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (373, 'An Italian baroque painter who was commissioned to make a great number of altar paintings for churches in the north of Italy.', 373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (374, 'CLASSICAL REALISM', 374, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (375, 'Raphael', 375, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (376, 'An Italian sixteenth century painter who was influential for his loose and impressionistic way of painting and use of colour, unusual for the period.', 376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (377, 'Raphael was commissioned to make many paintings for churches in Florence.', 377, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (378, 'He made a lot of working drawings and drew cartoons from which his paintings were traced.', 378, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (379, 'Titian', 379, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (380, 'Titian is a very influential Italian painter who made many altarpieces for churches in Florence and Rome but also used classical themes which gave him greater freedom of interpretation and therefore the space to experiment.', 380, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (381, 'Titian&#x2019;s style was much emulated, leading to many works being wrongly attributed to him in the twentieth century.', 381, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (382, 'He developed a style of painting that, like Raphael&#x2019;s, was looser and more impressionistic than his contemporaries.', 382, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (383, 'Titiian began to show that the surface of the painting and the way the paint is used could be just as important for the viewer as the subject of the painting.', 383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (384, 'It became important that the individuality and singularity of the painter&#x2019;s touch should be celebrated.', 384, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (385, 'Artists began to make paintings that were far more than a presentation of a narrative subject realising that the way paint was applied could reveal as much of the psychology of the subject as could the literal visual interpretation.', 385, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (386, 'Titian was one of the pioneers of this way of working, displayed in paintings like &#x2018;The Flaying of Marsyus&#x2019;, a four metre high painting which shows Marsyus tied to a tree as his flesh is cut off by several men in a crowd.', 386, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (387, 'Dogs at his feet feed on his flesh.', 387, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (388, 'Titian was also a great colourist and used daring and vivid combinations as can be seen in a crucifixion painted for the cathedral in the Italian city of Ancona.', 388, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (389, 'This shows his compositional skill too &#x2013; like many painters of the time Titian controlled the direction of the viewer&#x2019;s eye by carefully considered compositional elements, such as the twist of a body, the direction of the gaze of the subjects, the direction of a pointed arm, the flow of drapery and by the use of colour.', 389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (390, 'Diagonal trajectories were popular, so that the viewer might be led into the centre of a painting, and sometimes these became spirals that take the viewer&#x2019;s eye in several steps to the focal point of the composition.', 390, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (391, 'The use of red or another bright colour often indicated the focal point.', 391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (392, 'Titian often depicted Japanese or Chinese ceramics in his interiors, evidence that these were newly imported and popular in Italy at the time.', 392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (393, 'REALISM', 393, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (394, 'During the sixteenth century as the European nations vied for power, their monarchies became the main patrons of art.', 394, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (395, 'Court artists such as Velasquez painted the ruling families of Europe and had the time and financial backing to break new ground.', 395, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (396, 'Artists such as Velasquez, Chardin, or Van Dyck, for example, began to depict real life rather than fictional scenes, mythical or religious subjects, going beyond the formal portrait to paint events, objects and people that interested them.', 396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (397, 'History painting and still life were explored by an increasing number of painters.', 397, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (398, 'Diego Velasquez', 398, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (399, 'A painter by appointment to the Spanish court, Velasquez painted some of the best known works in the history of painting.', 399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (400, 'One of his most popular works shows the King Philip, the queen and the Infanta standing in an informal group with various servants in a room in the royal household looking out at the viewer.', 400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (401, 'Velasquez chose to show the family at home in intimate surroundings, several rooms beyond the room in which they stand visible through a door behind them.', 401, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (402, 'The family look out of the painting as if the viewer has trespassed upon them in their private quarters yet they regard the viewer with a challenging cool assurance.', 402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (403, 'The use of perspective and light and shade focuses the viewer&#x2019;s eye on the Infanta.', 403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (404, 'This painting does not have a literal narrative but neither is it a straight forward family portrait.', 404, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (405, 'Velasquez has taken a psychological approach to his subjects which was unusual at the time.', 405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (406, 'Velazquez also painted many portraits including one of King Philip on a rearing horse, and a portrait of the Infanta wearing a lacy dress.', 406, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (407, 'The detail of the spectacular red dress, the lace, embroidery and the jewels on it, is painted with thick squeezes of paint which viewed close up seem no more than rapid impressions and the viewer is very conscious of the physical properties of paint on canvas.', 407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (408, 'Viewed from a distance however the apparently crude application of paint is astoundingly like the fabric it portrays.', 408, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (409, 'The Rokeby Venus is one of Velasquez&#x2019;s best known works.', 409, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (410, 'It shows a reclining nude with her back to the viewer, her face, which stares directly at the viewer, visible in a mirror held in front of her on ribbons by a cherub with red and white feathered wings.', 410, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (411, 'This painting, like the one of the royal family, addresses the psychology of looking at paintings.', 411, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (412, 'It gives the viewer access to the subject but ensures by the choice of pose, composition and facial expression that the subject is portrayed as being aware that they are being observed.', 412, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (413, 'This ensures that the viewer cannot avoid acknowledging their own subjectivity.', 413, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (414, 'THE STILL LIFE', 414, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (415, 'Artists had begun to explore new subjects and the still life became an important genre of painting which reached its height in sixteenth and seventeenth century Europe.', 415, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (416, 'The still life had many forms, the most common being a table bearing an array of food and drink, a vase of flowers, or an arrangement of objects.', 416, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (417, 'The still life allowed the painter to display skill in the way the various items are painted and can be seen essentially as a close 0up view, in contrast to a painting of a scene or a person.', 417, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (418, 'The skin of a lemon, the shine and reflection on silver ware, the pattern on a pheasant&#x2019;s feathers, the weave of a rug, the petals of flowers all gave ample opportunity for displays of virtuosity.', 418, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (419, 'A typical food still life might have fruit piled casually on a plate, silver pitchers or goblets, a dead game bird, a candle, knives, glasses, some meat or fish.', 419, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (420, 'The food would usually have been chosen to present an impressive display so that anyone who saw the picture would be impressed by how the owner was able to live.', 420, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (421, 'Zubaran and Chardin were early exponents of the still life.', 421, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (422, 'Zubaran', 422, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (423, 'A Spanish sixteenth century artist who is known chiefly for his still lifes, Zubaran made several paintings of vegetables such as cabbages and pumpkins.', 423, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (424, 'In one such painting an array of vegetables is shown hanging from a line, tied on by string of varying lengths.', 424, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (425, 'The vegetables are set against a plain background.', 425, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (426, 'Chardin', 426, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (427, 'Like Zubaran, Chardin usually painted flowers and vegetables and was rigorous in his choice of subject and composition, often making very simple arrangements of one or two items and concentrating on painting them as realistically as possible.', 427, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (428, 'Similarly, paintings of flowers were a signal of wealth and many artists added flowers to combinations of other items.', 428, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (429, 'Later on the Dutch flower painters concentrated on the flowers alone, filling the canvas with vases of exotic mixed floral arrangements.', 429, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (430, 'These were also intended as displays of wealth, for only the richest could afford cut flowers.', 430, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (431, 'Some still life painting depicted only objects, perhaps a rustic plate and cup, a book and a lamp, or richly decorated precious items.', 431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (432, 'Kalf, a Dutch artist, painted a suit of armour cast onto a chair by a table covered with gold goblets and plates, the metal glows and shines and reflects fire and lamplight.', 432, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (433, 'Kalf&#x2019;s virtuosity is revealed by a close inspection of the painted shine, made from the tiniest and most carefully applied touches of a range of yellows, whites and ochre.', 433, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (434, 'Whereas most still life paintings have no narrative, the vanitas painting is a form of still life which depicts objects with an allegorical or symbolic significance.', 434, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (435, 'The vanitas might be painted to celebrate a particular person&#x2019;s interests and achievements through objects alone, or combined with a portrait of the person.', 435, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (436, 'The symbolism in vanitas painting is not always evident and some knowledge is required to interpret them.', 436, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (437, 'Skulls make an obvious and frequent appearance to represent mortality, as do books to represent learning, musical instruments, globes, sextants and telescopes to represent travel and the outside world.', 437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (438, 'However more obscure and personal items would have been significant only to the subject or commissioner of the painting and those that knew them.', 438, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (439, 'One of the best known vanitas paintings is Holbein&apos;s The Ambassadors.', 439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (440, 'Holbein', 440, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (441, 'An English artist working during the reign of Elizabeth the first, Holbein, like most artists of the time mostly painted to commission, recording the members of and activities of the royal Court.', 441, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (442, 'He made several distinctive standing portraits of the Queen including one in which she is wearing a white embroidered dress decorated with pearls, one of her father Henry VIII, and many other people, usually between fifty cm and one metre high.', 442, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (443, 'He also painted Sir Thomas More.', 443, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (444, 'The Ambassadors is a very well known painting which shows two bearded dressed in doublet and hose with cloaks edged with ermine and hats, standing either side of a sideboard and table.', 444, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (445, 'On the furniture are casually arranges various items, tropes, that represent elements of learning and knowledge which are prerequisite to public life.', 445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (446, 'Some of these are obvious, like the globe and compasses, the bible, others more obscure to us today.', 446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (447, 'In the centre of the painting is a curious trompe l&#x2019;oeil feature.', 447, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (448, 'Invisible to the viewer standing in front of the painting but for a smear like element, viewed from a specified angle a skull can be seen.', 448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (449, 'It is speculated that Holbein merely wanted to display his virtuosity, or that the painting was intended to be hung on a stairway where it would be reliably encountered at the requisite angle.', 449, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (450, 'Elizabethan artists often specialized in miniature painting.', 450, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (451, 'Miniatures were around ten cm high, often oval shaped very detailed head and shoulders portraits.', 451, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (452, 'They were used like photographs to carry a likeness of a person around.', 452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (453, 'The miniature had a strategic function too &#x2013; portraits of possible marriage partners could be conveyed to each party.', 453, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (454, 'This was important since marriages between members of the royal family and the nobility were often arranged between different nationalities for political reasons, and the couple would rarely have met before the marriage.', 454, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (455, 'During the Elizabethan period, Europe underwent great political upheavals as the Protestant and Catholic churches vied for power.', 455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (456, 'Alliances were forged and broken and the borders of modern Europe were drawn.', 456, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (457, 'By the seventeenth century Europe had entered a phase of prosperity.', 457, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (458, 'Amsterdam was the centre of the trade in goods from overseas and became a very wealth city.', 458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (459, 'Artists were employed to represent and display the wealth of the new merchant class.', 459, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (460, 'Venice was also a wealthy and powerful centre of trade, and it was painted many times by Canaletto.', 460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (461, 'Canaletto', 461, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (462, 'Canaletto is world famous for his scenes of Venice in panoramic format showing the grand canal and its palazzos with water traffic passing, painted in very accurate detail and bathed in a golden sunlight.', 462, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (463, 'Canaletto also spent some time in London and painted the Thames river front, including the Royal Naval College at Greenwich and St Paul&#x2019;s Cathedral.', 463, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (464, 'Canaletto&apos;s painting are among the most frequently stolen in the world.', 464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (465, 'The influence of Italian classical sculpture spread and statuary was an essential element in architectural design, interiors and gardens.', 465, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (466, 'There were many popular sculptors.', 466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (467, 'Canova', 467, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (468, 'An Italian classical sculptor who made a work called The Three Graces a two metre high white marble sculpture of three women in flowing robes holding hands dancing in a circle.', 468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (469, 'This sculpture has been stolen once.', 469, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (470, 'DUTCH PAINTING', 470, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (471, 'Dutch seventeenth century painting depicted domestic interiors inhabited by the merchant class.', 471, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (472, 'This was the first time people other than the ruling classes had been able to commission artists because of the new found wealth brought by the import and export business.', 472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (473, 'Painters such as Van Dyck, Rembrandt and Vermeer were not presenting images of authority and power, they were depicting the calm serenity of the domestic sphere, a feminine world inhabited temporarily by men.', 473, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (474, 'The paintings reproduced the architecture of the time and some artists such as Saenredam made this their subject.', 474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (475, 'Pieter De Hooch', 475, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (476, 'De Hooch painted the life of the Amsterdam merchant class in intimate detail.', 476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (477, 'He was painting at a time when this newly wealthy class wanted to display its wealth to the world, but women were still largely confined to the home.', 477, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (478, 'Windows were always open with light streaming in to spaces which were otherwise candlelit, and food was plentiful, even fruit (although this was evidently a luxury).', 478, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (479, 'De Hooch&#x2019;s paintings portrayed a range of subjects, for example in one a toddling child reaches up to the mound of apples on a woman&#x2019;s lap.', 479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (480, 'The woman is sitting on a stool on the stone flagged floor and there is a door leading into a room with a window in it behind her.', 480, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (481, 'The child is rosy cheeked and blonde.', 481, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (482, 'Another shows a back yard with red bricks laid and plants growing along a wall.', 482, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (483, 'The architecture of the houses, the brickwork, the construction of doors and windows, the flooring and soft furnishings are faithfully reproduced.', 483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (484, 'Johannes Vermeer', 484, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (485, 'Vermeer is famous for his painting The Card Players, which shows a group of people sitting round a table at night, the scene lit by lamp and candlelight.', 485, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (486, 'The light glows on the faces of the card players but this is a very dark painting.', 486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (487, 'One of the men in the painting stares out at the viewer.', 487, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (488, 'Vermeer painted numerous self portraits showing himself both as a young and old man, but like de Hooch he is best known for his paintings of domestic interiors, for example Woman at a Window and another painting of a woman playing the harpsichord.', 488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (489, 'His interiors usually show a room lit from one side by a window, with a door in an opposite wall.', 489, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (490, 'The furnishings are comfortable, the floor is often black and white stone tiles, and the walls panelled.', 490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (491, 'If a man is present he is placed by or looking out of the window.', 491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (492, 'The woman is often seated, and looking at the viewer or into the room although the woman playing the harpsichord is in profile.', 492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (493, 'Vermeer wanted to symbolise the different realms inhabited by men and women in the seventeenth century, the outside world and the domestic space.', 493, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (494, 'In Woman at a Window a map hangs on the wall behind the woman, as if to amplify this difference.', 494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (495, 'Woman with A Pearl Necklace is a very well known portrait of a young woman wearing a simple yellow and blue dress with fabric wrapped round her head and a peal necklace at her throat.', 495, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (496, 'Rembrandt van Rijn', 496, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (497, 'Rembrandt is acknowledged to be one of the greatest artists of all time.', 497, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (498, 'His paintings are celebrated for their treatment of light and for their psychological approach.', 498, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (499, 'He tried to show the personality and mood of the sitter, giving the viewer the opportunity to make an assessment about the kind of person they are looking at.', 499, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (500, 'Rembrandt used light to great effect, not just in the way he used painting to represent it but also in his composition, in how he places figures in relation to light sources.', 500, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (501, 'One of Rembrandts best known works is The Night Watch a painting of a group of people sitting in the dark with candlelight.', 501, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (502, 'Another is Girl at a Window which shows a young girl seated at a table looking up to a window through which light is streaming into the very dark interior.', 502, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (503, 'As with most of Rembrandt&#x2019;s work, light is the subject of this painting.', 503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (504, 'Pieter Saenredam', 504, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (505, 'Saenredam is noted for his church interiors which are generally quite small.', 505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (506, 'One shows the architecture of the Osterkerk in Amsterdam, with tall stone columns, a floor of black and white squares of marble, and people dwarfed by the height of the building.', 506, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (507, 'The composition is deceptively ordinary, apparently showing an everyday view of an interior, but the treatment of light in the painting is skilfull, producing an effect of great serenity.', 507, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (508, 'The predominantly black and white painting has its focal point in the black diamond shaped board hanging from one of the columns, concentrating the viewer&#x2019;s eye on the pattern of black and white, vertical lines and perspective planes in the composition.', 508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (509, 'During the seventeenth century Europe saw much political upheaval and many significant events took place.', 509, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (510, 'Artists recorded these events and began to take on a new role as commentators.', 510, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (511, 'HISTORY PAINTING', 511, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (512, 'Delacroix', 512, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (513, 'The iconic image of the revolution is Delacroix&#x2019;s Liberty at the Barricades.', 513, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (514, 'This shows Liberty, the female symbol of France, astride the barricades, a crowd swirling around her, and tricolour flags waving.', 514, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (515, 'Delacroix is one of the first artists to represent current events and his work prefigured the realism of the nineteenth century.', 515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (516, 'The French Revolution was a rich source of inspiration for artists and one of the chief exponents was David.', 516, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (517, 'Jacques Louis David', 517, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (518, 'David made one of the first topical political paintings, The Death of Marat.', 518, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (519, 'The painting was shown at the time it was made and was a direct interpretation of a recent and controversial event.', 519, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (520, 'It was also an innovative composition, showing Marat, dead in his bath by his own hand, the knife with which he had stabbed himself on the floor nearby.', 520, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (521, 'Only Marat&#x2019;s head and shoulders and arm are visible, his arm trailing over the side of the stone bath which is carved from a single block on a pedestal base.', 521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (522, 'The dead man wears a white cloth wound like a turban around his head which lolls on the side of the bath.', 522, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (523, 'In his other hand he clutches a book or a letter.', 523, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (524, 'His skin is cold and blue.', 524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (525, 'The date is, unusually, inscribed in the corner of the painting, drawing the viewer&#x2019;s attention to the fact that it was recent history.', 525, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (526, 'Theodore Gericault', 526, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (527, 'Another French artist who made topical history paintings, Gericault is known best for The Raft of the Medusa, a very large (2 metre high) painting which shows a shipwreck scene with the survivors clinging to a raft in a stormy sea.', 527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (528, 'This is a depiction of a real recent event in which sense it was a news picture, conveying very vividly the terror of the survivors so that people could imagine being there.', 528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (529, 'Francisco Goya', 529, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (530, 'One of the greatest painters in history, Goya is well known for his political paintings including The Disasters of War, The Execution of Maximilian (1814) and a series of works known as The Black Paintings.', 530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (531, 'His paintings are mostly small, around 150 cm high at most.', 531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (532, 'Goya&#x2019;s intention was to reveal to a wider public the cruelty of war and the harshness of life for ordinary people.', 532, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (533, 'He was also an innovator in terms of his use of paint and colour.', 533, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (534, 'The Execution of Maximilian (an emperor) shows a blindfolded man on the right of the canvas facing a firing squad on the right side.', 534, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (535, 'The scene takes place in front of a hill with some buildings behind it.', 535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (536, 'Smoke is coming from the soldiers&#x2019; rifles.', 536, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (537, 'The painting depicts the actual moment of execution and was made very soon after the event.', 537, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (538, 'Thus it is news reportage, depicting the deposition and execution of a ruling monarch.', 538, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (539, 'The Disasters of War are a series of around 30 etchings (about 40 cm high) showing scenes of carnage from the battlefield.', 539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (540, 'Soldiers lie dismembered and disembowelled on the ground, they hang from trees, decapitated or genitally mutilated.', 540, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (541, 'Goya intended to show the gross cruelty of war and because he chose to use etching his work reached a wide audience that might otherwise have been able to ignore the black paintings show the life of ordinary Spanish people eking out a subsistence living on the land, living in one room.', 541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (542, 'The paintings are dark and inky, there is no light.', 542, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (543, 'They show the harshness and ugliness of life.', 543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (544, 'There is one in the series that shows a dog in quicksand, an ochre sand hill filling most of the canvas with the dog&#x2019;s head sticking out of it.', 544, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (545, 'Eighteenth century Britain was a rural economy ruled by landed gentry.', 545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (546, 'Artists were in demand to record the ownership of land and houses for display by the new English landed gentry !Thomas Gainsborough.', 546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (547, 'One of the best known eighteenth century British artists, Gainsborough, made a painting showing a couple and their children with a hunting dog under a tree with a house in the background.', 547, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (548, 'The man wears breeches, a tail coat and a hat, and is leaning on a shotgun; the woman has on a fine low necked dress which is light blue and white with a straw hat.', 548, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (549, 'They are dressed in their country clothes, but there is no pretence &#x2013; this is a painting intended to display the couple&#x2019;s wealth and social status, showing them confidently engaging the viewer from the rural beauty of their large estate.', 549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (550, 'Joshua Reynolds', 550, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (551, 'Another English painter of the landed gentry, Reynolds made portraits and landscapes.', 551, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (552, 'English landscape painting was particularly important during a period when land ownership was the key to wealth.', 552, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (553, 'People commissioned paintings to show how much land they owned.', 553, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (554, 'George Stubbs', 554, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (555, 'Stubbs&apos; name is synonymous with his paintings of horses which are extremely realistically painted, in profile, on a plain background.', 555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (556, 'Other aspects of eighteenth century life are well represented by Rubens and Hogarth.', 556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (557, 'Peter Paul Rubens', 557, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (558, 'Rubens is known for his paintings of buxom rosy cheeked naked women.', 558, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (559, 'Rubens showed groups of women relaxing together, often out of doors, naked or semi clothed.', 559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (560, 'Their flesh is almost expressionistically painted and close to the range of colours used to paint the skin tones can clearly be seen.', 560, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (561, 'Rubens draws on the classical nude as inspiration but his nudes are ordinary women.', 561, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (562, 'William Hogarth', 562, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (563, 'From Hogarth, a British artist and political commentator and satirist, we have a comprehensive documentation of eighteenth century London life in his highly detailed drawings and engravings.', 563, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (564, 'His engravings of Bedlam, the notorious London hospital for the insane, are famous for their accurate depiction of a horrific place which few people had seen.', 564, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (565, 'Hogarth showed the seamy side of life, the injustices and inequities, but contrasted it with images of debauchery, gluttony and indulgence.', 565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (566, 'Franz Hals', 566, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (567, 'Dutch Eighteenth century painter notably of portraits, Hals&#x2019; painting The Laughing Cavalier, a portrait of a man in a large hat with a feather is instantly recognisable.', 567, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (568, 'William Blake', 568, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (569, 'English poet and artist William Blake is known for his visionary drawings and for his illustrated poetry books the Songs of Innocence and the Songs Of Experience.', 569, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (570, 'Blake made a drawing with watercolour of god measuring the world with a pair of compasses which has been much reproduced.', 570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (571, 'In the eighteenth century in Europe and America neo classicism and the study of Greek sculpture was a central part of any artist&#x2019;s education.', 571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (572, 'The highest accolades were given to those who could best emulate, interpret and appropriate classical Greek art, taking Greek literature as its narrative theme.', 572, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (573, 'Artists were expected to become skilful at drawing in a realistic style, and to be able to draw from life, model and carve the human form with accuracy.', 573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (574, 'But by the nineteenth century romanticism was beginning to take a hold and landscape and nature were idealised.', 574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (575, 'Anton Watteau', 575, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (576, 'A French artist working in the nineteenth century, Watteau made paintings of people in landscapes, often with classical allusions &#x2013; as was the fashion of the day the aristocracy was fond of acting the peasant (Marie Antoinette, for example) or dressing as mythological characters.', 576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (577, 'The paintings were often portrait commissions.', 577, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (578, 'Watteau was particularly good at painting trees &#x2013; at the time trees in paintings were rendered in much the same way by many artists, often by assistants rather than by the artist.', 578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (579, 'Watteau drew and painted virtually every leaf making the trees in his work very realistic and quite distinctive.', 579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (580, 'Fragonard', 580, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (581, 'Fragonard is known for his paintings of women and children in the countryside or in a garden.', 581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (582, 'Fragonard&#x2019;s many portraits depict an idyllic life, as in Girl on a Swing and his many paintings of society women and children in beautiful dresses.', 582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (583, 'Fragonard&#x2019;s paintings are full of trees, flowers and grass in the background, and the detail of the subjects&#x2019; clothes is given great attention.', 583, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (584, 'They are painted in a soft, feathery delicate style.', 584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (585, 'Arnold Bocklin', 585, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (586, 'During the 1960s Bocklin painted romantic landscapes and idyllic pastoral scenes showing shepherdesses and their swains in ribboned clothes with the occasional piece of statuary.', 586, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (587, 'Like Watteau he painted trees in great detail.', 587, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (588, 'Boucher', 588, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (589, 'Boucher also painted romantic landscapes.', 589, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (590, 'THE SUBLIME', 590, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (591, 'The worship of nature found its culmination in the German concept of the sublime, which described nature as vast and never ending, true beauty in which man is almost an irrelevance.', 591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (592, 'The chief exponent of this was Friedrich.', 592, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (593, 'Casper David Friedrich', 593, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (594, 'Freidrich was a romantic painter many of whose works were painted from nature on an island in the Baltic sea off the coast of Germany.', 594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (595, 'He was chiefly known for his interpretation of the Romantic sublime.', 595, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (596, 'Friedrich tried to create a rendering of nature so beautiful as to seem almost like heaven.', 596, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (597, 'This deeply subjective approach was of great interest to many critics and writers struggling with the idea of authorship, subjectivity and the purpose of art after Kant.', 597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (598, 'The sublime is also dealt with by Mary Shelley in Frankenstein and by English poets such as Wordsworth and Shelley.', 598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (599, 'Friedrich&apos;s paintings are usually less than 200 by 100 cm in size.', 599, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (600, 'They nearly always feature a solitary figure in a landscape.', 600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (601, 'A typical painting depicts a ruined folly on a hilltop seen on a moonlit night with a figure on another peak in the foreground.', 601, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (602, 'One painting shows a figure in a rain and windswept landscape with barren trees, another a figure in a moonlit garden with a balustrade, a classical statue and a broken urn.', 602, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (603, 'Friedrich painted in a cool reduced palette and his many dramatic moonlit scenes are rendered in shades of blue and grey.', 603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (604, 'John Martin', 604, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (605, 'An English artist working in the late nineteenth century, Martin painted a kind of inversion of the idea of the sublime.', 605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (606, 'His visionary scenes depicted humankind struggling with the natural world.', 606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (607, 'An example is a painting of a towering dark black and brown mountain at night in which a huge chasm opened up, a volcanic eruption spewing flames, sparks and lava into the darkness.', 607, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (608, 'Dwarfed by this landscape many people are struggling and fleeing from the lava flow and fires.', 608, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (609, 'English artists did not engage with the sublime but focused on the rural landscape around them and its inhabitants.', 609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (610, 'John Constable', 610, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (611, 'Constable was an eighteenth century artist who made one of the most famous English paintings, The Haywain, which shows a country scene in which a cart loaded with hay is travelling down a lane.', 611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (612, 'The cart and the farm workers that it carries is very small in relation to the picture as a whole.', 612, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (613, 'The painting consists mostly of trees and bushes, predominantly green, brown and ochre coloured with a blue sky.', 613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (614, 'It is a peaceful image of a summer day at harvest time.', 614, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (615, 'Flatford Mill is almost as well known.', 615, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (616, 'This painting shows a house on a millpond by a river where trees and vegetation predominate.', 616, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (617, 'Constable&#x2019;s paintings convey specific weather conditions and the time of day very well.', 617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (618, 'They seem to represent an idealised and valued vision of the countryside as a peaceful haven.', 618, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (619, 'Constable always added an element of red to each painting, a tiny dot or brushstroke of red paint that served to draw the viewer&#x2019;s eye into the part of the painting that he wanted them to focus on.', 619, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (620, 'It might be the roof of a distant cottage or, as in the Haywain, a red garment on a person on the cart.', 620, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (621, 'Other British painters such as Wilson Steer, Joseph Wright of Derby, John Everett Millais and Samuel Palmer explored both landscape and portraiture during the nineteenth century.', 621, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (622, 'In the second half of the century the industrial revolution changed life in Europe dramatically and the rural idyll was no longer given centre stage.', 622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (623, 'Although critics such as John Ruskin held up the values of traditional arts and crafts skills, and the study of classical art, artists on the whole discovered new challenges.', 623, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (624, 'Joseph Mallord Turner', 624, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (625, 'One of the best known British artist, often described as a British impressionist, Turner made semi abstract watercolours and oil paintings of the river Thames and London.', 625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (626, 'He was most interested in depicting weather and light conditions as opposed to landscape or architectural detail.', 626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (627, 'Turner&#x2019;s paintings are often brightly coloured and made with blurred brushy strokes.', 627, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (628, 'He had made one of the river Thames with a rainbow and one of a cloudy sky painted in white and grey.', 628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (629, 'Whistler was very critical of Turner, describing his work as mere daubing.', 629, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (630, 'James McNeil Whistler', 630, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (631, 'A painting of fireworks over the river Thames was said by Whistler&#x2019;s rival Turner to look as if someone had thrown a pot of paint at the canvas.', 631, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (632, 'Whistler made many partings of London, but he also had a house in the Lake District in the north of England and many of his landscapes are painted there, as well as domestic interiors and portraits.', 632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (633, 'Whistler also painted murals, for example one at Plas Newydd, the home of the Marquis of Anglesey, in Wales.', 633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (634, 'He prided himself in being able to paint very fast.', 634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (635, 'During the nineteenth century the styles of historical periods were being appropriated by contemporary artists.', 635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (636, 'Classicism, realism and romanticism were broad spectrums that included artist working in diverse ways.', 636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (637, 'Some movements were more specific in their aims and distinct in their visual output.', 637, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (638, 'THE PRE RAPHAELITES', 638, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (639, 'The Pre Raphaelites were a group of artists working in England who were inspired by poetry and medieval history.', 639, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (640, 'They painted people dressed in clothes inspired by medieval costume but in contemporary fashion, women and men characterised by their full lips and long flowing hair worn parted in the centre and loose.', 640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (641, 'The style of painting was exact and detailed, everything rendered with great realism, the intention being to convey ideal beauty and sentiment.', 641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (642, 'Often the paintings had a decorative border or architectural elements.', 642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (643, 'Pre Raphaelite painting and sculpture was highly stylised and extremely popular.', 643, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (644, 'Dante Gabriel Rossetti', 644, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (645, 'Rossetti was a leading figure in the pre Raphaelite Brotherhood, the society formed by artists and writers interested in working together.', 645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (646, 'These artists produced paintings that looked to medieval art and legend for their inspiration.', 646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (647, 'Rossetti&#x2019;s Lady of Shallot is a world famous painting of a drowned woman, the lover of King Arthur, floating in a stream.', 647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (648, 'She is face upwards and looks as if she is merely asleep, wearing a long green dress with her hair floating in a cloud around her head and her hands clasped on her breast.', 648, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (649, 'Flowers float in the water around her.', 649, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (650, 'Ford Maddox Brown', 650, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (651, 'One of the British pre Raphaelite painters, Maddox Brown made less stylised paintings than Rossetti, for example a painting of a goat in a barren landscape lit by a lurid setting sun, painted in orange, purple and green.', 651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (652, 'The poetic aesthetic extended to other artists.', 652, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (653, 'Henry Wallis', 653, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (654, 'A British nineteenth century painter who is best known for his painting of Henry Chatterton, a boy poet who committed suicide.', 654, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (655, 'The boy is shown on a bed with a view of a garden through a window behind him, wearing a white shirt which is loose.', 655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (656, 'Gustav Klimt', 656, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (657, 'An Austrian artist working at the turn of century in Vienna, Klimt painted highly decorative images of women with particular attention to the reproduction of the patterns on textiles and clothes the models are wearing.', 657, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (658, 'He also painted landscapes, giving the same attention to the &#x2018;pattern&#x2019; of leaves and flowers, such as in his series The Four Seasons, paintings of woodlands and gardens in seasonal colours.', 658, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (659, 'Klimt had a very distinctive style of drawing the figure, giving his almost exclusively female subjects a kind of languid beauty.', 659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (660, 'They are often draped in decadent poses or staring straight at the viewer giving an impression of forthrightness and unabashed hedonism.', 660, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (661, 'One example is a painting of a standing woman, her head almost resting on one shoulder, wearing an extraordinarily ornate dress and cloak which has a pattern of multicoloured and gold squares.', 661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (662, 'In fact Klimt&apos;s trademark was his use of tooled and flat gold leaf applied to the patterns on fabric in his paintings.', 662, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (663, 'He also tended to delineate the shape of the body by the outline of the clothes, so that the figure often appeared to be a solid block.', 663, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (664, 'These attributes give Klimt&#x2019;s work a graphic effect.', 664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (665, 'Another example is a painting of four women who are lying together on a bed.', 665, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (666, 'Klimt&#x2019;s paintings often show women together in intimacy, lying together in an embrace.', 666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (667, 'In this painting the four are intertwined and seen in a kind of false perspective as if from above.', 667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (668, 'It is hardly possible to tell which limbs belong to which head.', 668, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (669, 'The fabric of their clothes are mixed together, so that the composition is a swirl of heads, limbs and pattern, creating a kind of round shape within the frame of the canvas.', 669, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (670, 'Portrait painters were in great demand in a new social milieu ushered in by the industrial revolution and its resulting new wealth.', 670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (671, 'John Singer Sargent', 671, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (672, 'Sargent&apos;s paintings show fashionably dressed society figures, the fabric of their clothes very realistically painted, skin glowing and hair shining.', 672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (673, 'Berthe Morisot', 673, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (674, 'French artist Morisot is best known for her portraits and drawings.', 674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (675, 'Gwen John', 675, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (676, 'John&apos;s portraits are subtle and she used a sombre palette.', 676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (677, 'ORIENTALISM', 677, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (678, 'Art from Japan, China and the far east, both traditional and contemporary, began to appear in Europe and attracted a great deal of attention.', 678, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (679, 'Hokusai', 679, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (680, 'A Japanese eighteenth century artist who is best known for his painting The Wave, was a master of the woodcut and pen and ink drawing and painting.', 680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (681, 'The towering wave in this work is about to crash down on the surrounding sea, representing the power of nature.', 681, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (682, 'Hokusai worked in traditional style but his subject matter was innovative.', 682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (683, 'The Wave has become an instantly recognisable image.', 683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (684, 'Utamaro', 684, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (685, 'Utamaro&#x2019;s series of hand coloured woodcuts, the work for which he is best known, depicts a series of explicit sexual acts between men and geisha women dressed in elaborate kimonos.', 685, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (686, 'The women and men perform a range of often gymnastic sex acts and could not be shown in public since they were considered indecent.', 686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (687, 'These works are unusual at the time for their representation of enthusiastic and playful sexuality.', 687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (688, 'Overt sexuality was not a subject of art in the eighteenth century.', 688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (689, 'Religious beliefs in Europe would not tolerate the depiction of explicit sexual acts and Victorian Britain did not even permit allusive or veiled reference to sex.', 689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (690, 'A number of artists nevertheless made work on the subject, notably Beardsley.', 690, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (691, 'Beardsley Aubrey', 691, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (692, 'Beardsley was a graphic artist whose finely executed and intricate art nouveau style has become instantly recognisable.', 692, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (693, 'Beardsley illustrated Oscar Wilde&apos;s book of the tale of Salome, and made a large number of explicit sexual images.', 693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (694, 'Influenced by the art of China and Japan as were many at the time, Beardsley&apos;s characteristic flat highly decorative black and white pen and ink drawings made use of patterns on textiles and clothing of his subjects to great effect, and he was an extremely skilled draughtsman.', 694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (695, 'Many artists were influenced by contemporary developments in the new discipline of psychoanalysis, as well as other therapeutic and diagnostic methods of the day such as phrenology.', 695, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (696, 'Sigmund Freud was beginning his research into the unconscious which was to have a profound influence on artists in the late nineteenth and early twentieth century.', 696, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (697, 'Messerschmidt', 697, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (698, 'Messerschmidt was a German artist who in the 1890s made a series of small modelled heads cast in bronze, about ten cms across, a male head with a number of different expressions, often the features are contorted.', 698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (699, 'The heads are titled by the mood or emotion the face is displaying.', 699, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (700, 'Messerschmidt was influenced by contemporary developments in psychology.', 700, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (701, 'REALISM', 701, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (702, 'French realism profoundly influenced European art.', 702, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (703, 'Painters like Courbet, Corot, Greuze and Daumier began to try to represent landscape and the figure as objectively as possible.', 703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (704, 'Gustav Courbet', 704, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (705, 'The most influential of the early realists is Courbet who is often referred to as the father of realism.', 705, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (706, 'Both Manet and C&#xe9;zanne acknowledged his influence.', 706, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (707, 'Corot', 707, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (708, 'A contemporary of Courbet, Corot is known for his still calm scenes of the French countryside, often featuring roads and tracks and always trees, which he was particularly good at painting and some notable snow scenes.', 708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (709, 'Corot&#x2019;s paintings are small, no more than sixty cm high.', 709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (710, 'Camille Pissarro', 710, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (711, 'A French landscape painter who spent some time in London painting the river Thames.', 711, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (712, 'Pissarro liked the cool grey light of London.', 712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (713, 'Ingres', 713, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (714, 'Ingres made a painting of a seated nude which is known all over the world.', 714, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (715, 'It is a simple, natural and intimate portrait of a woman seated on a bed with her back to the viewer, a white sheet draped round her hips, and a red patterned scarf wound round her head with her face just visible in profile.', 715, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (716, 'It has been remarked that that drawing of the figure is anatomically inaccurate and that if the woman were to stand up her body would be very out of proportion.', 716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (717, 'Auguste Renoir', 717, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (718, 'Children and women are Renoir&#x2019;s favourite subjects.', 718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (719, 'His paintings are light bright celebrations of youth, beauty, the countryside, gardens and flowers.', 719, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (720, 'He painted himself often, the best known self portrait is one in which he is wearing a white painter&#x2019;s smock and a brown wide brimmed hat with glasses.', 720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (721, 'Renoir&#x2019;s nudes are fleshy and sensual, the paint applied to create a fuzzy, slightly out of focus effect.', 721, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (722, 'A particularly well known painting shows a little girl with very blonde hair in a dark blue dress standing in long grass and poppies.', 722, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (723, 'Gustave Caillebotte', 723, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (724, 'Caillebotte&apos;s landscapes and people are characterised by a richness in the way the paint is applied.', 724, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (725, 'A painting of men scraping and polishing a wooden floor is a well known example of his work.', 725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (726, 'The men, wearing dark trousers and white shirts, some wearing caps, are on their knees in a horizontal line across the canvas, working, and the floor has a bright shine on it, created by the daylight streaming through the windows at the back of the room.', 726, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (727, 'The painting is mainly dark brown and wood colour, with the windows and the shine on the floor painted in a bluish white.', 727, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (728, 'Puvis de Chavannes', 728, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (729, 'French painter of the early nineteenth century who made a painting of a thin young man with dark hair and eyes who is standing in a small boat on a lake.', 729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (730, 'The man is meant to make us think of Christ.', 730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (731, 'THE INVENTION OF PHOTOGRAPHY', 731, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (732, 'The realist painters were working just before photography.', 732, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (733, 'There was still no way of picturing the world other than to paint it.', 733, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (734, 'When photography was invented it had an immediate effect on painting because of the way a photograph defined a definite edge to an image.', 734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (735, 'In a painting the edge was always mutable and subjective.', 735, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (736, 'Manet and Degas began to compose their paintings in a different way, framing what they painted in a way that was closer to photography.', 736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (737, 'Edouard Manet', 737, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (738, 'The French artist who is often described as the father of impressionism, Manet painted in a realistic way but used paint expressively.', 738, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (739, 'Manet took great interest in the way a photograph cropped a scene and noted the difference for a painter, who can choose what to include and where.', 739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (740, 'Manet&#x2019;s work began to have a new look which was at first shocking but immediately influential.', 740, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (741, 'Manet was a prominent member of the community of artists in Paris and was friends with Courbet, Degas, and Monet.', 741, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (742, 'Manet painted two very well known works, Olympia, and Dejeuner Sur L&#x2019;Herbe, as well as Bonjour Monsieur Courbet and the Bar at the Folies B&#xe9;rg&#xe8;res.', 742, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (743, 'This last is a very original painting which depicts a bar at the Folies B&#xe9;rg&#xe8;res night club, visited and painted by many of his contemporaries, including Toulouse Lautrec, behind which a woman is serving.', 743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (744, 'On closer inspection what the viewer sees is actually the reflection in the mirror behind the bar.', 744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (745, 'Manet has taken this mirror as the edge of his painting and thus we see the woman&#x2019;s back, some of people at the bar and the bottles which are in front of the mirror.', 745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (746, 'What was striking at the time was that this was a painting of a reflection, and was not what it seemed to be at all.', 746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (747, 'Manet&apos;s paintings were startlingly new and inventive.', 747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (748, 'His Olympia (which owes much to Velasquez&#x2019;s Rokeby Venus) was considered shocking, provoked storms of protests and was rejected from the Paris salon, the official body of recognition for artists.', 748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (749, 'The painting was said to be pornographic and the public was outraged.', 749, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (750, 'Olympia is depicted nude, reclining on a couch, with her maid and a cat behind her.', 750, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (751, 'She wears a ribbon choker and earrings and seems to be a prostitute.', 751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (752, 'However it was the look on the woman&#x2019;s face that was controversial &#x2013; she stares out of the canvas at the viewers, actively acknowledging their presence and thus making them the subject of the work.', 752, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (753, 'This was revolutionary, and brought the whole history of the depiction of the female nude in art into question &#x2013; here a woman meets the viewer&#x2019;s gaze rather than allowing the viewer unchallenged access to her body in passive acquiescence.', 753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (754, 'Dejeuner Sur L&#x2019;Herbe, also a reworking of a historical painting, provoked a similar response but soon these two paintings were acknowledged as groundbreaking works.', 754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (755, 'Dejeuner Sur L&#x2019;Herbe shows a group of young men and women picnicking in the woods, one of the women is naked, reclining casually and staring out at the viewer from the centre of the canvas.', 755, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (756, 'The gaze of some of the others is also focused out of the picture plane at the viewer.', 756, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (757, 'Bonjour Monsieur Courbet is a painting in which Manet acknowledges his debt to Courbet.', 757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (758, 'He shows himself walking along a country lane, respectfully greeting the passing Courbet who carries a walking stick and wears a hat.', 758, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (759, 'Edgar Degas', 759, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (760, 'Degas is a contemporary of Manet&#x2019;s who also made use of the photograph in his compositions.', 760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (761, 'Degas is known all over the world for his scenes of ballet dancers rehearsing, which are instantly recognisable and often reproduced in particular as calendars.', 761, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (762, 'His paintings are cropped &#x2013; much like a photograph a figure will be half painted and cut off by the edge of the canvas.', 762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (763, 'He mainly painted women, including several paintings and drawings of women bathing.', 763, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (764, 'One of these shows the back of a woman with red hair as she crouches in a tin bath.', 764, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (765, 'There is a blue towel next to her on the floor.', 765, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (766, 'Degas made many bronze sculptures of ballet dancers, most are quite small ones around fifty cm high, as well as some of curled up dogs.', 766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (767, 'His best known and very popular sculpture The Little Dancer is larger, around two metres high.', 767, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (768, 'The little girl is realistically modelled and wears a net tutu, a bodice and ballet shoes.', 768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (769, 'It is rare to find a bronze sculpture which has added clothes.', 769, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (770, 'Paul C&#xe9;zanne', 770, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (771, 'Known as the father of modernist painting, C&#xe9;zanne was a French painter working in the mid nineteenth century.', 771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (772, 'He took the ideas of Manet and Courbet and developed a completely new style of painting.', 772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (773, 'Many see C&#xe9;zanne as the pivotal figure in late nineteenth century painting who laid the ground for Cubism.', 773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (774, 'C&#xe9;zanne lived in Paris and the south of France in a house called Jas de Buffon in Provence.', 774, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (775, 'The Provencal countryside featured in much of his work and C&#xe9;zanne liked to work out of doors as much as he could.', 775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (776, 'He also painted still lives and portraits.', 776, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (777, 'C&#xe9;zanne was working around the same time as the impressionists, but his ideas took him on a very different route.', 777, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (778, 'He had no interest in creating an impression, in depicting light, in optical fragmentation of the image.', 778, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (779, 'Rather he was concerned with how the three dimensional world could be rendered on a two dimensional plane.', 779, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (780, 'C&#xe9;zanne was one of the first artists to paint a representative image giving as much importance to the picture plane as to the illusory space of the painting.', 780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (781, 'In his landscapes and still lives he considered how much of an object he could paint, seeing no reason not to paint the parts of an object that could not be seen, to bend perspective, to remake nature.', 781, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (782, 'He composed his paintings so that the picture plane seemed to come towards the viewer, using judicious touches of white to control the path of the viewer&#x2019;s eye.', 782, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (783, 'It is in this that he was revolutionary and laid the ground for Picasso and Braque to develop Cubism, for as young artists they were astonished by what C&#xe9;zanne had done.', 783, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (784, 'He gave them the idea that a three dimensional object could be rendered in two dimensions not by creating an illusion, but by unfolding its various planes and presenting them with no relation to the actual physical integrity of the object.', 784, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (785, 'C&#xe9;zanne was also daring in his use of colour.', 785, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (786, 'He never covered the ground of the canvas completely, always leaving parts of it bare to function as a part of the painting as a whole.', 786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (787, 'He applied colour with an abstract sensibility, for its own sake as part of the painting, rather than as a part of a faithful depiction.', 787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (788, 'He used the juxtaposition of pure colours to create shadows of other colours.', 788, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (789, 'A number of paintings are immediately associated with C&#xe9;zanne.', 789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (790, 'The Bathers (a number of works bear this title) are a group of female nudes in a variety of poses, their bodies represented as planes in a landscape.', 790, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (791, 'The painting is brown and green, the bodies flesh coloured.', 791, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (792, 'This is C&#xe9;zanne&#x2019;s best known and least understood work, and it is the work which has the most influence on other artists.', 792, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (793, 'His still lifes of oranges and apples are also characteristic, as are some of his portraits, for example the woman with a green face (the green representing the shadow cast on her face by the hat she was wearing.', 793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (794, 'Most of his paintings are fairly small, under a metre high.', 794, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (795, 'He painted the land around his country home endlessly, often making repeated versions of the same view of trees and hillside.', 795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (796, 'He made a small landscape that includes a rectangular water cistern in which there is a mirror image, many paintings of trees including a small painting of a single almond tree in blossom, and views from the house.', 796, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (797, 'He often painted his wife, including a notable painting of her in the bath under greenish water.', 797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (798, 'IMPRESSIONISM', 798, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (799, 'Whilst C&#xe9;zanne was investigated the depiction of three dimensional space, a number of younger artists who were influenced by photography were experimenting with a new way of painting.', 799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (800, 'The photograph made realistic and accurate representations by artists redundant, since the photograph could do this quicker and more accurately.', 800, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (801, 'This fact, combined with a new acknowledgment of the subjectivity of art and an interest in the psyche, freed artists to try to make impressions of what they saw rather than try to replicate.', 801, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (802, 'Broadly speaking, the artist&#x2019;s role became one of subjective interpretation rather than of objective representation.', 802, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (803, 'The most dramatic example of this is the work of a number of painters working in France in the 1880s and 90s.', 803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (804, 'Claude Monet', 804, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (805, 'Monet is the best known of the Impressionists, and indeed made the painting which gave the movement its name, Impression: Sunrise, a view of the houses of parliament and the river Thames in London.', 805, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (806, 'This is a small painting of the river at sunrise, the water reflecting the oranges and pinks of the sun, which is painted as a small orange circle of relatively thick paint.', 806, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (807, 'This painting was remarkable for its vagueness in terms of detail, and for the consideration of the nature of the painted surface, so that the sun could be read both as a sun and as a painted circle.', 807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (808, 'Monet was trying to paint an impression of what he saw, as if with eyes half shut, and it is possible that he got this idea through seeing out of focus photographic images.', 808, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (809, 'After all the idea of a deliberately blurred image was a radically new one at the time and Monet&#x2019;s idea changed the aims of painters everywhere.', 809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (810, 'Monet took from C&#xe9;zanne the idea that an artist might paint what was in front of him but paint less than he actually saw, aiming to reproduce the essence of the view.', 810, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (811, 'To this end he developed a very distinctive painting style breaking the scene he was painting into patches of colour, applied without covering the ground of the canvas, using the uncovered white ground to create a shimmering effect.', 811, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (812, 'He used colour to paint light as well as solid forms.', 812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (813, 'Along with Matisse and Picasso, on whom he was influential, Monet is considered by many to be one of the greatest artists in the world and one of the founders of modernism and twentieth century painting.', 813, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (814, 'Monet made several important groups of works.', 814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (815, 'The Water Lily paintings that he made at his country home in Giverny, a series of fa&#xe7;ades of Rouen cathedral, and a series of Haystacks.', 815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (816, 'The water lilies series are largely three by four metre semi abstract canvases which depict a pond or lake with water lilies on it using shades of emerald, ultramarine and violet, with bright pink and red highlights on the usually white lilies.', 816, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (817, 'The way the paint is applied to construct the image is almost of as much importance as the image itself.', 817, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (818, 'A series of paintings of the fa&#xe7;ade of the cathedral at Rouen was a detailed exercise in and demonstration of impressionist technique.', 818, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (819, 'In these works the surface of the painting is encrusted with multicoloured paint, which is visible as a fa&#xe7;ade only at a distance.', 819, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (820, 'There are an immense variety of paintings which represent and exaggerate different light conditions.', 820, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (821, 'Monet was unique in his preference for continual repetition of views of the same subject.', 821, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (822, 'He also painted a haystack series, notable for their pale blue and lilac shadows, a houses of parliament and Thames series.', 822, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (823, 'Impressionism did not impress the Paris salon, leading to the formation of the Salon des Refus&#xe9;s, a place for all those artists rejected by the Salon to exhibit.', 823, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (824, 'It soon became recognised that these rejected artists were changing painting forever.', 824, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (825, 'Georges Seurat', 825, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (826, 'Known as the inventor of pointillism, Seurat made a number of large paintings in this style, the best known of which is L&#x2019;Ile de la Grande Jatte, as well as landscapes and coastal views.', 826, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (827, 'Pointillism is a way of painting using only tiny dots of separate colour.', 827, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (828, 'These dots merge at a certain distance to create an optical illusion of solid colour although there is a grainy quality to the painted image.', 828, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (829, 'L&#x2019;Ile de la Grande Jatte shows people enjoying themselves on a summer day on an island.', 829, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (830, 'In the foreground is a boy in swimming trunks wearing a red hat.', 830, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (831, 'Women and children walk in the gardens and under the trees and a group of picnickers sit on the grass.', 831, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (832, 'Alfred Sisley', 832, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (833, 'Sisley was an English painter who spent much time working in Paris.', 833, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (834, 'Sisley was the major exponent of the Impressionist style in Britain, painting London and the English countryside.', 834, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (835, 'Walter Sickert', 835, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (836, 'Like Sisley, Sickert painted London in an impressionistic style, although he is not an Impressionist.', 836, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (837, 'Sacker&#x2019;s paintings are all made in a gloomy palette of grey, ochre and brown, the paint thickly applied, showing scenes of London and portraits.', 837, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (838, 'Not all French painters worked in the impressionist style.', 838, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (839, 'Many artists developed individual ways of working that placed them outside any movement.', 839, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (840, 'SYMBOLISM', 840, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (841, 'James Ensor', 841, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (842, 'Belgian symbolist artist who lived in Ostend where his former home can still be visited.', 842, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (843, 'During the 1890s Ensor made a painting of a crowd of people including several in clown masks, one white masked person wearing top hat standing out in the foreground.', 843, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (844, 'The painting has a slightly nightmarish effect.', 844, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (845, 'Odilon Redon', 845, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (846, 'Belgian symbolist artist who made paintings, drawings and prints.', 846, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (847, 'One of his best known works is a drawing of a black spider.', 847, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (848, 'The Dutch artist Van Gogh was not part of any movement.', 848, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (849, 'His style was idiosyncratic and he made his work in relative isolation, not knowing success in his own lifetime.', 849, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (850, 'Vincent Van Gogh', 850, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (851, 'Van Gogh came from a poor family and he was supported financially throughout his life by his brother Theo who became an art dealer and bought all of Van Gogh&#x2019;s early work.', 851, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (852, 'Their relationship is well documented by letters.', 852, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (853, 'Without Theo, Van Gogh would not have been able to paint and as it was he lived much of the time on very little money.', 853, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (854, 'Van Gogh began by drawing and painting what he saw around him, rural scenes from his home village showing people working in the fields.', 854, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (855, 'He made his famous charcoal drawing The Potato Eaters, which shows a poor family eating a meagre meal crammed into one room in the semi darkness.', 855, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (856, 'Van Gogh moved to his own lodgings in Paris but continued to paint rural life.', 856, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (857, 'He also painted his own surroundings, producing another seminal work The Artist&#x2019;s Bedroom, which shows a small bed, a chair with a straw seat, a pair of boots by the bed.', 857, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (858, 'The perspective is exaggerated and the drawing chunky.', 858, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (859, 'He outlined the shapes of things, developing what was to become his unique style.', 859, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (860, 'He also painted his own boots, which amounted to a self portrait.', 860, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (861, 'During his time in Paris and later on in Arles, Van Gogh met many other artists and became particular friends with Paul Gauguin who had a great influence on him.', 861, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (862, 'Van Gogh began to paint still life, and in particular flowers, influenced by the fashion for oriental decorative arts which had recently begun to arrive in Paris.', 862, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (863, 'He even made a painting of a cherry tree which has Japanese characters round its borders.', 863, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (864, 'Van Gogh&#x2019;s most famous work, also one of the most famous paintings in the world, is Sunflowers, a painting of a number of sunflowers in a vase, the whole done in a palette of ochre, yellow and brown with Van Gogh&#x2019;s usual thick encrustations of paint and impasto.', 864, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (865, 'This work is now priceless.', 865, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (866, 'A similar work, Irises, is worth billions.', 866, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (867, 'Van Gogh and his close friend the painter Paul Gauguin rented a house in Arles in the south of France where the light was very good for painting, where they lived and worked, both drinking heavily.', 867, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (868, 'Van Gogh made many of his best works here but it was in Arles that his increasing depression began to take its toll.', 868, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (869, 'He painted the portraits of many local people, including the school master, the postman, a local prostitute who modelled for him, and notoriously his own self portraits.', 869, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (870, 'One of these shows him as a red headed bearded man with pale green eyes wearing a suit.', 870, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (871, 'But one self portrait is notorious for showing the artist with a bandage round his head covering his ear.', 871, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (872, 'He is reputed to have cut off his own ear when drunk and sent it to a woman with whom he was angry.', 872, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (873, 'Van Gogh sold only to his brother in his lifetime and his talent was not recognised.', 873, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (874, 'This probably contributed to his increasing drinking and ill health.', 874, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (875, 'Towards the end of his life he painted a number of landscapes that popular myth supposes presage his death, cornfields with brooding dark skies and black crows flying, the birds painted with black paint squeezed straight from the tube.', 875, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (876, 'He often used paint in an unmediated way which was unusual at the time, and it was his use of paint that first brought him to attention, although his subject matter on the whole was conventional.', 876, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (877, 'The myths created around Van Gogh&#x2019;s life have been enhanced by a Hollywood film made in the 1960s in which Kirk Douglas portrays Van Gogh as the ultimate tortured soul putting his life into his art.', 877, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (878, 'Paul Gauguin', 878, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (879, 'Gauguin&#x2019;s early works were landscapes and portraits.', 879, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (880, 'Gauguin was an outspoken person and influential among the artists of Paris.', 880, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (881, 'He was a very close friend of Van Gogh and they lived together in Arles in the south of France for a time.', 881, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (882, 'Gauguin supported Van Gogh and encouraged him, helping him through periods of madness including the ear dismembering incident.', 882, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (883, 'Gauguin&#x2019;s paintings are mainly bold and colourful figurative works.', 883, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (884, 'Towards the end of his life Gauguin moved to Tahiti (where he later died) and painted the works with which he is most readily associated (although they are not necessarily seen as his best), showing Tahitian people, often women, in native dress, with the interiors of traditional homes and beach scenes.', 884, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (885, 'The colours he uses are very strong, bold and sun drenched.', 885, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (886, 'Pierre Bonnard', 886, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (887, 'Bonnard&#x2019;s domestic interiors are painted in warm and subtle shades with soft dabbing brushstrokes, and his attention to the pattern and detail of the textiles in the room is an important part of the whole composition.', 887, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (888, 'In one painting a woman is seated at a table at the top of the canvas, the table extending towards the bottom, the perspective elongated which is designed to draw the viewer in and give the impression both of welcome and of distance.', 888, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (889, 'Much of Bonnard&#x2019;s work presents people in solitary and restful states.', 889, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (890, 'Edouard Vuillard', 890, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (891, 'Like Bonnard, Vuillard painted landscapes and domestic interiors.', 891, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (892, 'Henri de Toulouse Lautrec', 892, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (893, 'Toulouse Lautrec was a graphic artist who was friends with many of the artist of fin de si&#xe8;cle Paris.', 893, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (894, 'He is best known for his posters for the Folies B&#xe9;rg&#xe8;re in particular for one showing a row of can can dancers.', 894, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (895, 'He was a very good draughtsman and was influence by Chinese and Japanese art.', 895, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (896, 'Henri Rousseau', 896, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (897, 'Rousseau&#x2019;s painting of a tiger in a jungle has become extremely well known.', 897, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (898, 'The jungle is shown as a mass of enormous green leaves and stalks that cover the canvas, below which stalks a partially obscured tiger.', 898, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (899, 'There are a number of other animals, birds and exotic blooms.', 899, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (900, 'The painting is executed in a faux na&#xef;ve illustrative style.', 900, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (901, 'Rousseau also made a painting of a parade in a French town, he often represented French civic life and was a Republican.', 901, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (902, 'FAUVISM', 902, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (903, 'Andre Derain', 903, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (904, 'Another group of French artists led by Andre Derain and influenced by both C&#xe9;zanne and Monet painted in a style that they called Fauvism, meaning literally &#x2018;wildness&#x2019;.', 904, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (905, 'They worked in very bright pure colours, using larger areas of colour than the impressionists and plenty of white space, not attempting to create a recognisable image but to reduce the image to a wild approximation of its essential qualities.', 905, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (906, 'Although Impressionist painting became very popular, it was the work of C&#xe9;zanne that inspired the next generation of artists, notably Matisse, Picasso, Gris and Braque to break new ground.', 906, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (907, 'CUBISM', 907, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (908, 'Georges Braque', 908, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (909, 'A French artist born around 1880, Braque, along with Picasso, was the major exponent of Cubism, a new style of painting that fragmented and distorted the image in a radical way.', 909, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (910, 'Although he began as a painter of landscapes and portraits, in 1911 Braque made a painting on which he pasted a piece of newspaper, Still Life with a Guitar.', 910, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (911, 'It showed a table, a bottle and a guitar but treated all objects as if conventional perspective did not apply, representing them instead with flat planes, areas and shapes.', 911, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (912, 'The newspaper signified the presence of a newspaper in the still life, but was not a newspaper and did not look like one.', 912, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (913, 'The act of sticking something onto the canvas initiated a revolution in painting, because it destroyed the integrity of the picture plane by acknowledging its physicality as a surface.', 913, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (914, 'This had the effect of allowing a painting to be seen as an object as well as a flat representation.', 914, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (915, 'No one had ever stuck anything onto a canvas to make part of the image before.', 915, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (916, 'Braque&#x2019;s achievement was to find a new way of representing form.', 916, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (917, 'He began to include collage, using old tickets and printed paper (in one painting he uses paper printed with a rattan pattern to signify a cane chair), in another a piece of wood effect paper is used for a guitar for example.', 917, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (918, 'He made many such collages often depicting bottles, tabletops and wine glasses with the structural planes of the objects opened out and repositioned, before going on, as did Picasso, to attempt the same thing exclusively with paint.', 918, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (919, 'Cubism was a way of representing all the planes of three dimensional objects on a two dimensional plane, to think of every object in terms of the surfaces of a series of cubes for the purposes of painting.', 919, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (920, 'This way of looking at the physical world had been initiated by C&#xe9;zanne.', 920, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (921, 'Such a radical restructuring of pictorial space resulted in paintings made in browns and greys initially.', 921, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (922, 'Braque sometimes used an elliptical canvas.', 922, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (923, 'The paintings gave the impression of crystalline forms with recognisable elements attached, such as a head, an eye, part of a guitar, the side of a bottle, the front of a table, the back of a chair.', 923, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (924, 'Gradually Braque began to make a different kind of image becuase the effect of cubism had been to free the picture plane from the constraints of realistic representation and pictorial space.', 924, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (925, 'The surface of the canvas became the pictorial space, so that the painting was both a representation and an exploration of surface.', 925, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (926, 'Juan Gris', 926, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (927, 'A painter working at the same time and in a similar way to Braque.', 927, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (928, 'It is possible that Gris was the first to use collage on a painting, although Braque is given the credit for this.', 928, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (929, 'Gris tended to make small paintings, sometimes using an oval format.', 929, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (930, 'He also went on to make Cubist paintings.', 930, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (931, 'Pablo Picasso', 931, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (932, 'The Spanish artist Picasso is considered to be the greatest modern artist in the world.', 932, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (933, 'Picasso&#x2019;s work progressed through a number of different styles, including Cubism, and he made work in a variety of media.', 933, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (934, 'His skill at drawing is consistently evident, but he was equally good at sculpture.', 934, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (935, 'From Picasso&#x2019;s early career, his Blue period is the best known.', 935, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (936, 'This describes a number of figurative paintings that have a blue light cast on them, for example a boy with a dove in his hand, and a young boy dressed as a Harlequin balancing on a ball.', 936, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (937, 'The dove and the clown, particularly Harlequin and Pierrot, were recurring motifs throughout Picasso&#x2019;s life.', 937, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (938, 'In the early 1900s Picasso, along with Braque and Gris, would have seen African sculptures for the first time when a collection was exhibited in Paris.', 938, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (939, 'This, combined with C&#xe9;zanne&#x2019;s experiments with the picture plane, led the three artists to make the first Cubist works.', 939, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (940, 'Although Cubism is most readily attributed to Picasso, it was Gris who in fact made the first Cubist collage.', 940, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (941, 'Picasso made a number of these collages featuring bottles, guitars, as well as some small sculptures including one of a shelf with some domestic objects on it made from rough bits of wood and painted with a bobble braid tacked along the front.', 941, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (942, 'Picasso made a great number of Cubist paintings, which are rarely more than a metre high and predominantly brownish or greyish.', 942, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (943, 'During this period Picasso began to develop his mature style to reach its greatest achievement in two paintings, Guernica and Les Demoiselles D&#x2019;Avignon.', 943, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (944, 'Guernica was painted in 1917 to commemorate General Franco&#x2019;s massacre of a Spanish village.', 944, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (945, 'In it Picasso wanted to show the horror of war and suffering, and he was conscious of making a painting which would get attention.', 945, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (946, 'He made the painting immediately after the event and it was intended to be given to the town of Guernica.', 946, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (947, 'It is a very large painting, three meters by six, which shows a number of figures based clearly on African sculpture (for example Dogon masks) painted in black, purple, white and grey with everything outlined in black.', 947, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (948, 'Guernica is an image of horror, of death and suffering, of weeping women, corpses and maimed bodies.', 948, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (949, 'The limbs of the figures are intertwined so that the whole painting operates as an abstract composition as well.', 949, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (950, 'This was the first time a modern artist had made a painting that was such an explicit criticism of the government of the day.', 950, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (951, 'Guernica was shocking and reproductions of the painting were instantly printed in newspapers all over the world.', 951, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (952, 'Les Demoiselles D&#x2019;Avignon is composed along similar lines but depicts a more pleasant scene of naked women in the countryside, painted in flesh tones and greens.', 952, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (953, 'However, the women have the same mask like faces as the figures in Guernica.', 953, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (954, 'A film was made of Picasso making this painting, showing how he drew out the figures with continuous lines never once correcting himself or erasing anything.', 954, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (955, 'Picasso painted many portraits, often of the various women in his life, including Dora Maar, one of his lovers.', 955, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (956, 'These were never flattering, as the Cubist style which Picasso had made his own led to features being rearranged so that an eye might appear on the side of the head and the face be cut in two.', 956, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (957, 'Black painted lines delineate everything and colour is entirely unrealistic.', 957, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (958, 'Picasso made a great deal of carved and assembled sculpture including a bull&#x2019;s head made from a bicycle seat with a pair of handlebars for horns.', 958, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (959, 'Drawing underpinned everything that Picasso did, and he made a large number of them, in particularly a number of black line drawings of the Minotaur, a myth which fascinated him.', 959, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (960, 'Later in he made coloured lithographs that look like pastel drawings.', 960, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (961, 'These which are very well known, for example a simple hand holding a bunch of flowers and a dove with an olive branch in its beak.', 961, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (962, 'In his exploration of every medium Picasso included ceramics, producing a great many plates, vases, and other objects, that he painted on and he also made a series of tooled and embossed silver platters.', 962, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (963, 'Juan Miro', 963, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (964, 'Picasso&#x2019;s compatriot Miro took a very different route, making abstract paintings that drew on a variety of sources.', 964, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (965, 'Miro uses amorphous shapes reminiscent of microscopic life forms that are painted on a thinly prepared raw linen ground.', 965, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (966, 'Thin black lines and spidery nodes connect amorphous shapes in red and blue.', 966, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (967, 'Miro borrowed compositional elements from comic strip drawings in particular the American Krazy Kat.', 967, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (968, 'He also made collages using images cut from cutlery, tool and machinery catalogues that were often mixed with elements from cartoon strips and then abstracted to produce his paintings.', 968, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (969, 'In some ways Miro&#x2019;s approach had an affinity with the work of the surrealists.', 969, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (970, 'Few artists have come close to achieving Picasso&#x2019;s huge output in such a variety of media.', 970, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (971, 'But one French artist made paintings that were as influential as Picasso&#x2019;s.', 971, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (972, 'Henri Matisse', 972, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (973, 'Matisse is considered one of the greatest artists in the world.', 973, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (974, 'His paintings include the famous Dance, an 8 metre by 3 metre panoramic painting of dancing female nudes, radical for its semi abstraction.', 974, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (975, 'The pink figures become rhythmic arabesques on the swirling blue ground.', 975, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (976, 'Matisse later made the figures into paper cut outs, a form in which he was prolific in later life, using ultramarine paper collaged onto a white ground.', 976, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (977, 'With the Snail, a large 4 by 3 metre collage made of a spiral of squares of different brightly coloured pieces of paper within a yellow collaged frame, these cut outs became Matisse&apos;s best known work, their graphic simplicity lending itself well to printed reproduction.', 977, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (978, 'The blue dancers, their heavy limbs creating a calligraphic pattern, are one of the most recognisable works by a twentieth century artist.', 978, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (979, 'Matisse also made a large number of drawings; he had an assured hand, creating very simple drawings often using one continuous line.', 979, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (980, 'In his paintings it is Matisse&#x2019;s use of drawing which sets his work apart.', 980, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (981, 'He allowed a drawn edge to define the pictorial space and function both as part of an object or structure and part of the composition, and similarly he left areas of the canvas unpainted, allowing the white of the ground to function as part of the image.', 981, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (982, 'Matisse painted restful, joyous and domestic subjects in an entirely unsentimental, intellectual way.', 982, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (983, 'His composition was daring, for example the Piano Lesson is a predominantly green and red painting composed of large blocks of colour, the entire painting bisected by a diagonal line, the head of a boy emerging from behind a piano very small in relation to the very large canvas.', 983, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (984, 'The painting is figurative but it verges toward abstraction.', 984, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (985, 'It is this abstract sensibility and his use of colour which singles Matisse out.', 985, 1, '1.1', 0);
